module.exports = {"indexHtml":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"theme-color\" content=\"#090D16\">\n  <title>AWS Student Builder Community Day 2026 | Rungta University, Bhilai</title>\n  <meta name=\"description\" content=\"BUILD. LEARN. CONNECT. Free developer conference for student cloud builders on 22 August 2026 at Rungta University, Bhilai.\">\n\n  <!-- Google Fonts: Inter & JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n  <!-- Core Stylesheet from Reference Site -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Syne:wght@600;700;800&family=JetBrains+Mono:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"app.css\">\n\n  <style>\n    :root {\n      --font-inter: 'Inter', -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n      --font-jetbrains: 'JetBrains Mono', monospace;\n    }\n    body {\n      font-family: var(--font-inter);\n      background-color: var(--color-bg-base, #090D16);\n      color: var(--color-text-primary, #F0F6FC);\n      overflow-x: hidden;\n    }\n\n    /* Modal Overlay & Card matching dark theme */\n    .reg-modal-overlay {\n      position: fixed;\n      inset: 0;\n      background: rgba(9, 13, 22, 0.88);\n      backdrop-filter: blur(12px);\n      -webkit-backdrop-filter: blur(12px);\n      z-index: 10000;\n      display: none;\n      align-items: center;\n      justify-content: center;\n      padding: 1.5rem;\n      animation: fadeIn 0.25s ease-out forwards;\n    }\n    .reg-modal-overlay.active {\n      display: flex !important;\n    }\n    .reg-modal-card {\n      background: #0d1322;\n      border: 1px solid var(--color-border-bright, #485468);\n      border-radius: 20px;\n      max-width: 540px;\n      width: 100%;\n      max-height: 90vh;\n      overflow-y: auto;\n      padding: 2rem;\n      position: relative;\n      box-shadow: 0 25px 60px rgba(0, 0, 0, 0.85), 0 0 30px rgba(124, 58, 237, 0.25);\n    }\n    .modal-close-btn {\n      position: absolute;\n      top: 1.25rem;\n      right: 1.25rem;\n      background: rgba(255, 255, 255, 0.05);\n      border: 1px solid rgba(255, 255, 255, 0.1);\n      width: 36px;\n      height: 36px;\n      border-radius: 50%;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: var(--color-text-secondary, #8B949E);\n      font-size: 1.2rem;\n      cursor: pointer;\n      transition: all 0.2s ease;\n    }\n    .modal-close-btn:hover {\n      background: rgba(255, 255, 255, 0.15);\n      color: #fff;\n      transform: scale(1.05);\n    }\n    .modal-step-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 0.5rem;\n      font-family: var(--font-jetbrains);\n      font-size: 0.75rem;\n      font-weight: 700;\n      color: var(--color-text-accent, #00F0FF);\n      background: rgba(0, 245, 160, 0.1);\n      border: 1px solid rgba(0, 245, 160, 0.25);\n      padding: 0.3rem 0.75rem;\n      border-radius: 999px;\n      margin-bottom: 0.75rem;\n    }\n    .reg-form-group {\n      margin-bottom: 1.1rem;\n      text-align: left;\n    }\n    .reg-form-group label {\n      display: block;\n      font-size: 0.8125rem;\n      font-weight: 600;\n      color: var(--color-text-secondary, #8B949E);\n      margin-bottom: 0.4rem;\n      font-family: var(--font-jetbrains);\n    }\n    .reg-form-group label span.req {\n      color: #f85149;\n    }\n    .reg-input {\n      width: 100%;\n      background: #070a12;\n      border: 1px solid var(--color-border-medium, #30363D);\n      border-radius: 10px;\n      padding: 0.8rem 1rem;\n      color: #fff;\n      font-size: 0.9375rem;\n      outline: none;\n      transition: all 0.2s ease;\n    }\n    .reg-input:focus {\n      border-color: var(--color-text-accent, #00F0FF);\n      box-shadow: 0 0 15px rgba(0, 245, 160, 0.2);\n    }\n    .reg-grid-2 {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 1rem;\n    }\n    @media (max-width: 600px) {\n      .reg-grid-2 {\n        grid-template-columns: 1fr;\n      }\n    }\n    .pass-ticket-card {\n      background: linear-gradient(135deg, rgba(17, 23, 38, 0.95), rgba(9, 13, 22, 0.98));\n      border: 2px solid var(--color-text-accent, #00F0FF);\n      border-radius: 16px;\n      padding: 1.5rem;\n      margin-top: 1.25rem;\n      position: relative;\n      box-shadow: 0 0 35px rgba(0, 245, 160, 0.25);\n    }\n    .pass-ticket-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      border-bottom: 1px dashed rgba(255, 255, 255, 0.15);\n      padding-bottom: 1rem;\n      margin-bottom: 1rem;\n    }\n    .ticket-id-tag {\n      font-family: var(--font-jetbrains);\n      font-size: 1.15rem;\n      font-weight: 800;\n      color: var(--color-aws-amber, #FF9900);\n      letter-spacing: 0.05em;\n    }\n    .ticket-grid {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 0.8rem;\n      text-align: left;\n      font-size: 0.875rem;\n      margin-bottom: 1.2rem;\n    }\n    .ticket-grid-item label {\n      display: block;\n      font-size: 0.72rem;\n      color: var(--color-text-muted, #57606A);\n      text-transform: uppercase;\n      font-family: var(--font-jetbrains);\n    }\n    .ticket-grid-item div {\n      color: #fff;\n      font-weight: 600;\n    }\n    .ticket-actions {\n      display: flex;\n      flex-direction: column;\n      gap: 0.75rem;\n      margin-top: 1rem;\n    }\n    .btn-wa-direct {\n      background: #25D366;\n      color: #000;\n      font-weight: 700;\n      padding: 0.9rem 1.25rem;\n      border-radius: 10px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 0.5rem;\n      text-decoration: none;\n      font-size: 0.95rem;\n      transition: transform 0.2s ease, box-shadow 0.2s ease;\n      box-shadow: 0 4px 18px rgba(37, 211, 102, 0.35);\n    }\n    .btn-wa-direct:hover {\n      transform: translateY(-2px);\n      box-shadow: 0 6px 24px rgba(37, 211, 102, 0.5);\n    }\n    .btn-ticket-secondary {\n      background: rgba(255, 255, 255, 0.06);\n      border: 1px solid var(--color-border-medium, #30363D);\n      color: var(--color-text-primary, #F0F6FC);\n      padding: 0.75rem;\n      border-radius: 10px;\n      font-size: 0.85rem;\n      font-weight: 600;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 0.5rem;\n      transition: all 0.2s ease;\n    }\n    .btn-ticket-secondary:hover {\n      background: rgba(255, 255, 255, 0.12);\n      border-color: var(--color-text-secondary, #8B949E);\n    }\n    .admin-nav-pill {\n      display: inline-flex;\n      align-items: center;\n      gap: 0.4rem;\n      background: rgba(124, 58, 237, 0.15);\n      border: 1px solid rgba(124, 58, 237, 0.4);\n      color: #38bdf8;\n      font-size: 0.8125rem;\n      font-weight: 600;\n      padding: 0.5rem 0.9rem;\n      border-radius: var(--radius-md);\n      text-decoration: none;\n      transition: all 0.2s ease;\n    }\n    .admin-nav-pill:hover {\n      background: rgba(124, 58, 237, 0.3);\n      border-color: #38bdf8;\n      color: #fff;\n    }\n  \n    /* === AWWWARDS / GODLY / DRIBBBLE DESIGN INSPIRATION ADDITIONS === */\n    \n    /* Top Announcement Ribbon */\n    .top-announcement-ribbon {\n      background: linear-gradient(90deg, rgba(255, 153, 0, 0.18), rgba(0, 245, 160, 0.15), rgba(139, 92, 246, 0.18));\n      border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n      padding: 0.55rem 1.25rem;\n      font-size: 0.8125rem;\n      text-align: center;\n      position: relative;\n      z-index: 1001;\n      backdrop-filter: blur(10px);\n      -webkit-backdrop-filter: blur(10px);\n    }\n    .announcement-inner {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 0.75rem;\n      flex-wrap: wrap;\n    }\n    .pulse-dot {\n      display: inline-block;\n      width: 8px;\n      height: 8px;\n      border-radius: 50%;\n      background: #10b981;\n      box-shadow: 0 0 12px #10b981;\n      animation: pulseDot 2s infinite ease-in-out;\n    }\n    @keyframes pulseDot {\n      0%, 100% { transform: scale(1); opacity: 1; }\n      50% { transform: scale(1.4); opacity: 0.4; }\n    }\n    .announcement-text {\n      color: #e2e8f0;\n      letter-spacing: 0.02em;\n    }\n    .announcement-text strong {\n      color: var(--color-aws-amber, #FF9900);\n      font-family: var(--font-jetbrains);\n    }\n    .announcement-cta {\n      background: rgba(255, 255, 255, 0.1);\n      border: 1px solid rgba(255, 255, 255, 0.2);\n      color: #fff;\n      font-size: 0.75rem;\n      font-weight: 700;\n      font-family: var(--font-jetbrains);\n      padding: 0.2rem 0.6rem;\n      border-radius: 999px;\n      cursor: pointer;\n      transition: all 0.2s ease;\n    }\n    .announcement-cta:hover {\n      background: var(--color-aws-amber, #FF9900);\n      color: #000;\n      border-color: var(--color-aws-amber, #FF9900);\n    }\n\n    /* Ambient Auroras (Godly/Awwwards style) */\n    .aurora-bg {\n      position: fixed;\n      inset: 0;\n      pointer-events: none;\n      z-index: 0;\n      overflow: hidden;\n    }\n    .aurora-blob {\n      position: absolute;\n      border-radius: 50%;\n      filter: blur(140px);\n      opacity: 0.16;\n      animation: auroraFloat 20s ease-in-out infinite alternate;\n    }\n    .aurora-blob--1 {\n      width: 520px;\n      height: 520px;\n      background: #ff9900;\n      top: -120px;\n      left: 15%;\n    }\n    .aurora-blob--2 {\n      width: 600px;\n      height: 600px;\n      background: #00f0ff;\n      top: 35%;\n      right: -100px;\n      animation-delay: -6s;\n    }\n    .aurora-blob--3 {\n      width: 480px;\n      height: 480px;\n      background: #8b5cf6;\n      bottom: 5%;\n      left: 10%;\n      animation-delay: -12s;\n    }\n    @keyframes auroraFloat {\n      0% { transform: translate(0, 0) scale(1); }\n      50% { transform: translate(60px, 90px) scale(1.15); }\n      100% { transform: translate(-50px, -70px) scale(0.9); }\n    }\n\n    /* Kinetic Infinite Marquee (Godly style) */\n    .kinetic-marquee-section {\n      padding: 1.75rem 0;\n      overflow: hidden;\n      position: relative;\n      background: rgba(9, 13, 22, 0.7);\n      border-top: 1px solid rgba(255, 255, 255, 0.08);\n      border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n    }\n    .marquee-track {\n      display: flex;\n      gap: 1.5rem;\n      width: max-content;\n      animation: marqueeScroll 45s linear infinite;\n    }\n    .marquee-track--reverse {\n      animation: marqueeScrollReverse 45s linear infinite;\n      margin-top: 0.85rem;\n    }\n    .marquee-track:hover {\n      animation-play-state: paused;\n    }\n    @keyframes marqueeScroll {\n      0% { transform: translateX(0); }\n      100% { transform: translateX(-50%); }\n    }\n    @keyframes marqueeScrollReverse {\n      0% { transform: translateX(-50%); }\n      100% { transform: translateX(0); }\n    }\n    .marquee-tag {\n      display: inline-flex;\n      align-items: center;\n      gap: 0.6rem;\n      font-family: var(--font-jetbrains);\n      font-size: 0.825rem;\n      font-weight: 700;\n      letter-spacing: 0.06em;\n      color: #f0f6fc;\n      white-space: nowrap;\n      padding: 0.4rem 1rem;\n      background: rgba(255, 255, 255, 0.035);\n      border: 1px solid rgba(255, 255, 255, 0.09);\n      border-radius: 999px;\n      transition: all 0.25s ease;\n    }\n    .marquee-tag:hover {\n      background: rgba(255, 153, 0, 0.15);\n      border-color: rgba(255, 153, 0, 0.5);\n      color: #fff;\n    }\n    .marquee-tag .star {\n      color: var(--color-aws-amber, #FF9900);\n      font-size: 0.8rem;\n    }\n\n    /* Card Spotlight Hover Effect (Godly & Awwwards) */\n    .card-spotlight {\n      position: relative;\n      overflow: hidden;\n      transition: transform 0.3s cubic-bezier(0.2, 0, 0, 1), box-shadow 0.3s ease;\n    }\n    .card-spotlight::before {\n      content: '';\n      position: absolute;\n      inset: 0;\n      background: radial-gradient(circle 300px at var(--mouse-x, -500px) var(--mouse-y, -500px), rgba(255, 153, 0, 0.15), transparent 70%);\n      opacity: 0;\n      transition: opacity 0.3s ease;\n      pointer-events: none;\n      border-radius: inherit;\n      z-index: 1;\n    }\n    .card-spotlight:hover::before {\n      opacity: 1;\n    }\n\n    /* Interactive Schedule Track Filters (Mobbin & Collect UI) */\n    .schedule-filters {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 0.6rem;\n      justify-content: center;\n      margin-bottom: 2.5rem;\n    }\n    .schedule-filter-btn {\n      font-family: var(--font-jetbrains);\n      font-size: 0.8125rem;\n      font-weight: 600;\n      padding: 0.6rem 1.2rem;\n      border-radius: 999px;\n      background: rgba(255, 255, 255, 0.04);\n      border: 1px solid rgba(255, 255, 255, 0.1);\n      color: #94a3b8;\n      cursor: pointer;\n      transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n    .schedule-filter-btn:hover {\n      color: #fff;\n      border-color: rgba(255, 255, 255, 0.25);\n    }\n    .schedule-filter-btn.active {\n      background: rgba(255, 153, 0, 0.15);\n      border-color: var(--color-aws-amber, #FF9900);\n      color: #fff;\n      box-shadow: 0 0 20px rgba(255, 153, 0, 0.25);\n    }\n\n    /* 3D Tilt Card (Awwwards/Dribbble) */\n    .tilt-card {\n      transform-style: preserve-3d;\n      transition: transform 0.2s ease-out;\n    }\n\n    /* Holographic Digital Pass (Dribbble/Behance) */\n    .hologram-pass {\n      position: relative;\n      background: linear-gradient(145deg, #0d1424, #080c16);\n      border-radius: 20px;\n      padding: 3px;\n      box-shadow: 0 25px 60px rgba(0,0,0,0.85), 0 0 40px rgba(0, 245, 160, 0.25);\n      margin-top: 1.5rem;\n      overflow: hidden;\n    }\n    .hologram-pass-inner {\n      background: #090e1a;\n      border-radius: 17px;\n      padding: 1.75rem;\n      position: relative;\n      z-index: 2;\n    }\n    .hologram-watermark {\n      position: absolute;\n      right: -20px;\n      bottom: -20px;\n      opacity: 0.04;\n      pointer-events: none;\n      font-size: 15rem;\n      font-family: var(--font-jetbrains);\n      font-weight: 900;\n      color: #fff;\n    }\n    .barcode-scanner-box {\n      position: relative;\n      background: #03060c;\n      border: 1px solid rgba(255,255,255,0.1);\n      border-radius: 10px;\n      padding: 0.85rem 1rem;\n      margin: 1.25rem 0;\n      overflow: hidden;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 0.35rem;\n    }\n    .barcode-stripes {\n      height: 38px;\n      width: 85%;\n      background: repeating-linear-gradient(90deg, #fff, #fff 2px, transparent 2px, transparent 4px, #fff 4px, #fff 7px, transparent 7px, transparent 9px, #fff 9px, #fff 10px, transparent 10px, transparent 14px);\n      opacity: 0.85;\n    }\n    .laser-scan-line {\n      position: absolute;\n      top: 0;\n      bottom: 0;\n      width: 3px;\n      background: #00f0ff;\n      box-shadow: 0 0 10px #00f0ff, 0 0 20px #00f0ff;\n      animation: laserSweep 2.8s ease-in-out infinite alternate;\n    }\n    @keyframes laserSweep {\n      0% { left: 5%; opacity: 0.9; }\n      100% { left: 95%; opacity: 0.9; }\n    }\n\n    /* Floating Toast Notification (Mobbin/Collect UI) */\n    .toast-notification {\n      position: fixed;\n      bottom: 2rem;\n      right: 2rem;\n      background: rgba(13, 19, 34, 0.96);\n      border: 1px solid var(--color-text-accent, #00F0FF);\n      color: #fff;\n      padding: 0.85rem 1.4rem;\n      border-radius: 999px;\n      box-shadow: 0 15px 40px rgba(0,0,0,0.85), 0 0 25px rgba(0, 245, 160, 0.35);\n      backdrop-filter: blur(16px);\n      -webkit-backdrop-filter: blur(16px);\n      z-index: 100000;\n      display: flex;\n      align-items: center;\n      gap: 0.65rem;\n      font-family: var(--font-jetbrains);\n      font-size: 0.85rem;\n      transform: translateY(100px);\n      opacity: 0;\n      transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);\n      pointer-events: none;\n    }\n    .toast-notification.show {\n      transform: translateY(0);\n      opacity: 1;\n    }\n\n    /* Mobile Floating Bar (One Page Love / Land-book) */\n    .mobile-floating-bar {\n      display: none;\n      position: fixed;\n      bottom: 1.25rem;\n      left: 1.25rem;\n      right: 1.25rem;\n      background: rgba(9, 13, 22, 0.92);\n      border: 1px solid rgba(255, 255, 255, 0.18);\n      backdrop-filter: blur(16px);\n      -webkit-backdrop-filter: blur(16px);\n      border-radius: 999px;\n      padding: 0.55rem 0.85rem 0.55rem 1.35rem;\n      z-index: 9999;\n      justify-content: space-between;\n      align-items: center;\n      box-shadow: 0 15px 45px rgba(0,0,0,0.9), 0 0 25px rgba(255, 153, 0, 0.25);\n    }\n    @media (max-width: 768px) {\n      .mobile-floating-bar {\n        display: flex;\n      }\n    }\n    .mobile-floating-info {\n      display: flex;\n      flex-direction: column;\n      text-align: left;\n    }\n    .mobile-floating-date {\n      font-size: 0.78rem;\n      font-weight: 700;\n      color: #fff;\n      font-family: var(--font-jetbrains);\n    }\n    .mobile-floating-seats {\n      font-size: 0.72rem;\n      color: #10b981;\n      font-weight: 600;\n    }\n    .mobile-floating-btn {\n      background: var(--color-aws-amber, #FF9900);\n      color: #000;\n      font-weight: 800;\n      font-size: 0.8125rem;\n      padding: 0.65rem 1.15rem;\n      border-radius: 999px;\n      border: none;\n      cursor: pointer;\n      font-family: var(--font-jetbrains);\n      box-shadow: 0 4px 15px rgba(255, 153, 0, 0.4);\n    }\n\n  \n    /* ========================================================\n       OBSIDIAN CYBER-AURORA (AWWWARDS / ANTIGRAVITY THEME)\n       Colors: Obsidian Void (#050508) + Cyber Mint (#00f5a0)\n       + Electric Violet (#7c3aed / #a855f7) + Solar Amber (#ff6b35)\n       ======================================================== */\n    :root {\n      --color-bg-base: #050508 !important;\n      --color-bg-surface: #0a0c16 !important;\n      --color-bg-surface-hover: #101424 !important;\n      --color-bg-overlay: rgba(5, 5, 8, 0.92) !important;\n      --color-bg-glass: rgba(12, 16, 28, 0.72) !important;\n\n      --color-text-primary: #f8fafc !important;\n      --color-text-secondary: #94a3b8 !important;\n      --color-text-muted: #64748b !important;\n\n      /* High-impact Brand Accents */\n      --color-aws-blue: #7c3aed !important;        /* Electric Violet */\n      --color-aws-blue-hover: #6d28d9 !important;\n      --color-aws-amber: #00f5a0 !important;       /* Cyber Mint Emerald */\n      --color-aws-amber-hover: #00d98b !important;\n      --color-text-accent: #00f5a0 !important;\n      --color-cyan-glow: #00f5a0 !important;\n\n      --color-purple-neon: #a855f7 !important;\n      --color-solar-flame: #ff6b35 !important;\n\n      --color-border-subtle: rgba(255, 255, 255, 0.08) !important;\n      --color-border-medium: rgba(255, 255, 255, 0.14) !important;\n      --color-border-bright: rgba(168, 85, 247, 0.4) !important;\n      --color-border-glow: rgba(0, 245, 160, 0.4) !important;\n\n      --glow-blue: 0 0 30px rgba(124, 58, 237, 0.5) !important;\n      --glow-amber: 0 0 30px rgba(0, 245, 160, 0.45) !important;\n      --glow-cyan: 0 0 30px rgba(0, 245, 160, 0.5) !important;\n\n      --font-display: 'Syne', sans-serif !important;\n      --font-body: 'Space Grotesk', sans-serif !important;\n    }\n\n    body {\n      background-color: #050508 !important;\n      font-family: 'Space Grotesk', sans-serif !important;\n      color: #f8fafc !important;\n    }\n\n    /* Film Grain Noise Texture */\n    .bg-film-grain {\n      position: fixed;\n      inset: 0;\n      width: 100%;\n      height: 100%;\n      pointer-events: none;\n      z-index: 99999;\n      opacity: 0.038;\n      background-image: url(\"data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E\");\n    }\n\n    /* Architectural Typography */\n    .display-heading, .h1, .h2, .about__title, .cta__title, .why__card-title,\n    .countdown__value, .hero-stats__value, .timeline__title {\n      font-family: 'Syne', sans-serif !important;\n      letter-spacing: -0.02em !important;\n    }\n\n    /* Hero Heading Gradient */\n    .hero__word--3 {\n      background: linear-gradient(135deg, #00f5a0 0%, #a855f7 50%, #ff6b35 100%) !important;\n      -webkit-background-clip: text !important;\n      -webkit-text-fill-color: transparent !important;\n      filter: drop-shadow(0 0 30px rgba(0, 245, 160, 0.4)) !important;\n    }\n\n    /* Buttons: Electric Violet with Cyber Mint Glow */\n    .btn--primary {\n      background: linear-gradient(135deg, #7c3aed 0%, #9333ea 100%) !important;\n      border: 1px solid rgba(168, 85, 247, 0.5) !important;\n      box-shadow: 0 4px 25px rgba(124, 58, 237, 0.45) !important;\n      color: #fff !important;\n      transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1) !important;\n    }\n    .btn--primary:hover:not(:disabled) {\n      background: linear-gradient(135deg, #6d28d9 0%, #7e22ce 100%) !important;\n      box-shadow: 0 8px 35px rgba(168, 85, 247, 0.7) !important;\n      transform: translateY(-2px) !important;\n    }\n    .btn--secondary {\n      background: linear-gradient(135deg, #00f5a0 0%, #00d9f5 100%) !important;\n      color: #050508 !important;\n      font-weight: 800 !important;\n      border: none !important;\n      box-shadow: 0 4px 20px rgba(0, 245, 160, 0.4) !important;\n    }\n    .btn--secondary:hover:not(:disabled) {\n      box-shadow: 0 8px 30px rgba(0, 245, 160, 0.6) !important;\n      transform: translateY(-2px) !important;\n    }\n\n    /* Top Announcement Ribbon */\n    .top-announcement-ribbon {\n      background: linear-gradient(90deg, rgba(124, 58, 237, 0.25), rgba(0, 245, 160, 0.18), rgba(255, 107, 53, 0.2)) !important;\n      border-bottom: 1px solid rgba(168, 85, 247, 0.25) !important;\n    }\n    .pulse-dot {\n      background: #00f5a0 !important;\n      box-shadow: 0 0 15px #00f5a0 !important;\n    }\n    .announcement-text strong {\n      color: #00f5a0 !important;\n    }\n\n    /* Ambient Auroras */\n    .aurora-blob--1 {\n      background: #7c3aed !important;\n      opacity: 0.22 !important;\n    }\n    .aurora-blob--2 {\n      background: #00f5a0 !important;\n      opacity: 0.18 !important;\n    }\n    .aurora-blob--3 {\n      background: #ff6b35 !important;\n      opacity: 0.16 !important;\n    }\n\n    /* Kinetic Marquee */\n    .kinetic-marquee-section {\n      background: rgba(5, 5, 8, 0.85) !important;\n      border-color: rgba(168, 85, 247, 0.15) !important;\n    }\n    .marquee-tag {\n      background: rgba(124, 58, 237, 0.08) !important;\n      border-color: rgba(168, 85, 247, 0.2) !important;\n    }\n    .marquee-tag .star {\n      color: #00f5a0 !important;\n    }\n    .marquee-tag:hover {\n      background: rgba(0, 245, 160, 0.15) !important;\n      border-color: #00f5a0 !important;\n    }\n\n    /* Card Spotlight Hover */\n    .card-spotlight::before {\n      background: radial-gradient(circle 320px at var(--mouse-x, -500px) var(--mouse-y, -500px), rgba(0, 245, 160, 0.16), transparent 70%) !important;\n    }\n\n    /* Timeline Section & Cards */\n    .timeline__line {\n      background: linear-gradient(180deg, #7c3aed 0%, #00f5a0 50%, #ff6b35 100%) !important;\n    }\n    .timeline__node {\n      border-color: #00f5a0 !important;\n      box-shadow: 0 0 20px rgba(0, 245, 160, 0.5) !important;\n      color: #00f5a0 !important;\n    }\n    .timeline__card {\n      background: #090c18 !important;\n      border-color: rgba(255, 255, 255, 0.08) !important;\n    }\n    .timeline__card:hover {\n      border-color: rgba(0, 245, 160, 0.4) !important;\n      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8), 0 0 20px rgba(0, 245, 160, 0.2) !important;\n    }\n    .timeline__time {\n      color: #00f5a0 !important;\n    }\n\n    /* Schedule Filters */\n    .schedule-filter-btn.active {\n      background: rgba(0, 245, 160, 0.15) !important;\n      border-color: #00f5a0 !important;\n      color: #00f5a0 !important;\n      box-shadow: 0 0 20px rgba(0, 245, 160, 0.3) !important;\n    }\n\n    /* Holographic Ticket Pass */\n    .hologram-pass {\n      background: linear-gradient(145deg, #0f1322, #070912) !important;\n      box-shadow: 0 25px 60px rgba(0, 0, 0, 0.9), 0 0 45px rgba(0, 245, 160, 0.25) !important;\n    }\n    .ticket-id-tag {\n      color: #00f5a0 !important;\n      font-family: var(--font-jetbrains) !important;\n    }\n    .laser-scan-line {\n      background: #00f5a0 !important;\n      box-shadow: 0 0 12px #00f5a0, 0 0 24px #00f5a0 !important;\n    }\n    .btn-wa-direct {\n      background: linear-gradient(135deg, #00f5a0 0%, #00d9f5 100%) !important;\n      color: #050508 !important;\n      font-weight: 800 !important;\n      box-shadow: 0 6px 25px rgba(0, 245, 160, 0.45) !important;\n    }\n\n    /* CTA Banner Section */\n    .cta__card {\n      background: linear-gradient(135deg, rgba(14, 18, 32, 0.95), rgba(7, 9, 16, 0.98)) !important;\n      border-color: rgba(168, 85, 247, 0.35) !important;\n      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.9), 0 0 40px rgba(124, 58, 237, 0.35) !important;\n    }\n    .cta__glow {\n      background: radial-gradient(circle, rgba(124, 58, 237, 0.35) 0%, rgba(0, 245, 160, 0.15) 50%, transparent 80%) !important;\n    }\n\n    /* Navbar Glass */\n    .navbar--scrolled {\n      background-color: rgba(5, 5, 8, 0.88) !important;\n      border-bottom-color: rgba(168, 85, 247, 0.2) !important;\n      box-shadow: 0 4px 30px rgba(0, 0, 0, 0.8), 0 0 20px rgba(124, 58, 237, 0.15) !important;\n    }\n    .admin-nav-pill {\n      background: rgba(124, 58, 237, 0.15) !important;\n      border-color: rgba(168, 85, 247, 0.4) !important;\n      color: #c084fc !important;\n    }\n    .admin-nav-pill:hover {\n      background: rgba(124, 58, 237, 0.35) !important;\n      border-color: #a855f7 !important;\n      color: #fff !important;\n    }\n\n    /* Floating Toast */\n    .toast-notification {\n      background: rgba(10, 12, 22, 0.96) !important;\n      border-color: #00f5a0 !important;\n      box-shadow: 0 15px 45px rgba(0, 0, 0, 0.9), 0 0 30px rgba(0, 245, 160, 0.35) !important;\n    }\n\n    /* Mobile Floating Bar */\n    .mobile-floating-bar {\n      background: rgba(8, 10, 18, 0.94) !important;\n      border-color: rgba(168, 85, 247, 0.3) !important;\n      box-shadow: 0 15px 50px rgba(0, 0, 0, 0.95), 0 0 30px rgba(0, 245, 160, 0.3) !important;\n    }\n    .mobile-floating-btn {\n      background: linear-gradient(135deg, #00f5a0 0%, #00d9f5 100%) !important;\n      color: #050508 !important;\n      font-weight: 800 !important;\n      box-shadow: 0 4px 20px rgba(0, 245, 160, 0.45) !important;\n    }\n\n  </style>\n</head>\n<body class=\"font-sans antialiased\">\n  <div class=\"bg-film-grain\" aria-hidden=\"true\"></div>\n\n  <!-- AWWWARDS / GODLY TOP ANNOUNCEMENT BANNER -->\n  <aside class=\"top-announcement-ribbon\" role=\"region\" aria-label=\"Announcement\">\n    <div class=\"announcement-inner\">\n      <span class=\"pulse-dot\" aria-hidden=\"true\"></span>\n      <span class=\"announcement-text\">\n        <strong>REGISTRATIONS OPEN:</strong> AWS Student Builder Community Day '26 @ Rungta University, Bhilai\n      </span>\n      <button type=\"button\" class=\"announcement-cta\" onclick=\"document.getElementById('navRegBtn').click()\">\n        Claim Free Pass ➔\n      </button>\n    </div>\n  </aside>\n\n  <!-- GODLY AMBIENT LIGHT AURORAS -->\n  <div class=\"aurora-bg\" aria-hidden=\"true\">\n    <div class=\"aurora-blob aurora-blob--1\"></div>\n    <div class=\"aurora-blob aurora-blob--2\"></div>\n    <div class=\"aurora-blob aurora-blob--3\"></div>\n  </div>\n\n\n  <!-- Top Scroll Progress Bar -->\n  <div class=\"scroll-progress-bar\" id=\"scrollProgressBar\" style=\"transform: scaleX(0);\" aria-hidden=\"true\"></div>\n\n  <!-- Page Wrapper -->\n  <div class=\"page-wrapper\">\n\n    <!-- NAVBAR -->\n    <header class=\"navbar\" id=\"navbar\">\n      <div class=\"container navbar__inner\">\n        <a class=\"navbar__brand\" aria-label=\"AWS Student Builder Community Day Home\" href=\"#\">\n          <div class=\"navbar__logo-badge\">\n            <img alt=\"AWS SBCD Logo\" width=\"28\" height=\"28\" style=\"border-radius:8px;object-fit:cover\" src=\"images/logo.png\" onerror=\"this.src='public/images/logo.png'\"/>\n          </div>\n          <div class=\"navbar__brand-text\">\n            <span class=\"navbar__brand-title\">AWS SBCD '26</span>\n            <span class=\"navbar__brand-tag\">BUILD • LEARN • CONNECT</span>\n          </div>\n        </a>\n\n        <nav aria-label=\"Main Navigation\">\n          <ul class=\"navbar__nav\">\n            <li><a href=\"#experience\" class=\"navbar__link\">Experience</a></li>\n            <li><a href=\"#schedule\" class=\"navbar__link\">Schedule</a></li>\n            <li><a href=\"#community\" class=\"navbar__link\">Community</a></li>\n            <li><a href=\"#venue\" class=\"navbar__link\">Venue</a></li>\n            <li><a href=\"#faq\" class=\"navbar__link\">FAQ</a></li>\n            </ul>\n        </nav>\n\n        <div class=\"navbar__actions\">\n          <a href=\"admin.html\" class=\"admin-nav-pill\" title=\"Open Admin Dashboard\">\n            <span>⚡ Admin Console ↗</span>\n          </a>\n          <button type=\"button\" class=\"btn btn--primary\" id=\"navRegBtn\">\n            <span>Register Free</span>\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12h14\"></path><path d=\"m12 5 7 7-7 7\"></path></svg>\n          </button>\n        </div>\n      </div>\n    </header>\n\n    <!-- MAIN CONTENT -->\n    <main id=\"main-content\">\n\n      <!-- HERO SECTION -->\n      <section class=\"hero-section\">\n        <div class=\"cloud-canvas-container\">\n          <canvas class=\"cloud-canvas\" id=\"cloudCanvas\" aria-hidden=\"true\"></canvas>\n        </div>\n        <div class=\"hero-bg-grid\" aria-hidden=\"true\"></div>\n        <div class=\"hero-bg-glow\" aria-hidden=\"true\"></div>\n\n        <div class=\"container hero__content\">\n          <div class=\"hero__badge\">\n            <span class=\"hero__badge-dot\"></span>\n            <span>AWS Student Builder Community Day 2026</span>\n          </div>\n\n          <h1 class=\"display-heading hero__heading\">\n            <span class=\"hero__word hero__word--1\">BUILD.</span>\n            <span class=\"hero__word hero__word--2\">LEARN.</span>\n            <span class=\"hero__word hero__word--3\">CONNECT.</span>\n          </h1>\n\n          <p class=\"hero__subheading\">\n            A premium builder experience bringing students, developers and innovators together for one unforgettable day of learning, networking and creation.\n          </p>\n\n          <div class=\"hero__meta-bar\">\n            <div class=\"hero__meta-pill\">\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8 2v4\"></path><path d=\"M16 2v4\"></path><rect width=\"18\" height=\"18\" x=\"3\" y=\"4\" rx=\"2\"></rect><path d=\"M3 10h18\"></path></svg>\n              <span>22 August 2026</span>\n            </div>\n            <div class=\"hero__meta-pill\">\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><polyline points=\"12 6 12 12 16 14\"></polyline></svg>\n              <span>9:00 AM – 5:00 PM IST</span>\n            </div>\n            <a href=\"https://maps.app.goo.gl/J7DvAnneeEWmdWRQ8\" target=\"_blank\" class=\"hero__meta-pill\" style=\"cursor:pointer; text-decoration:none;\" title=\"Open in Google Maps\">\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z\"></path><circle cx=\"12\" cy=\"10\" r=\"3\"></circle></svg>\n              <span>Rungta University, Bhilai, Chhattisgarh ↗</span>\n            </a>\n            <div class=\"hero__meta-pill\">\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"></path><circle cx=\"9\" cy=\"7\" r=\"4\"></circle><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"></path><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"></path></svg>\n              <span>500+ Attendees</span>\n            </div>\n          </div>\n\n          <div class=\"hero__actions\">\n            <button type=\"button\" class=\"btn btn--primary btn--lg\" id=\"heroRegBtn\">\n              <span>Register Now</span>\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12h14\"></path><path d=\"m12 5 7 7-7 7\"></path></svg>\n            </button>\n            <a href=\"#experience\" class=\"btn btn--outline btn--lg\">\n              <span>Explore Event</span>\n            </a>\n          </div>\n\n          <!-- COUNTDOWN TIMER -->\n          <div class=\"hero__countdown-wrapper\">\n            <div class=\"countdown-container\">\n              <span class=\"countdown__title\">✦ COUNTDOWN TO COMMUNITY DAY ✦</span>\n              <div class=\"countdown__grid\">\n                <div class=\"countdown__card\">\n                  <span class=\"countdown__value\" id=\"cdDays\">00</span>\n                  <span class=\"countdown__label\">Days</span>\n                </div>\n                <div class=\"countdown__card\">\n                  <span class=\"countdown__value\" id=\"cdHours\">00</span>\n                  <span class=\"countdown__label\">Hours</span>\n                </div>\n                <div class=\"countdown__card\">\n                  <span class=\"countdown__value\" id=\"cdMinutes\">00</span>\n                  <span class=\"countdown__label\">Minutes</span>\n                </div>\n                <div class=\"countdown__card\">\n                  <span class=\"countdown__value\" id=\"cdSeconds\">00</span>\n                  <span class=\"countdown__label\">Seconds</span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- STATS CARDS -->\n          <div class=\"hero__stats-wrapper\">\n            <div class=\"hero-stats-container\">\n              <div class=\"hero-stats__grid\">\n                <div class=\"hero-stats__card\">\n                  <span class=\"hero-stats__value\">500+</span>\n                  <span class=\"hero-stats__label\">Student Builders</span>\n                </div>\n                <div class=\"hero-stats__card\">\n                  <span class=\"hero-stats__value\">8+</span>\n                  <span class=\"hero-stats__label\">Sessions & Workshops</span>\n                </div>\n                <div class=\"hero-stats__card\">\n                  <span class=\"hero-stats__value\">1</span>\n                  <span class=\"hero-stats__label\">Unforgettable Day</span>\n                </div>\n                <div class=\"hero-stats__card\">\n                  <span class=\"hero-stats__value\">∞</span>\n                  <span class=\"hero-stats__label\">Opportunities</span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <a href=\"#about\" class=\"hero__scroll-indicator\" aria-label=\"Scroll to about section\">\n            <span>EXPLORE EVENT</span>\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"hero__scroll-arrow\"><path d=\"m6 9 6 6 6-6\"></path></svg>\n          </a>\n        </div>\n      </section>\n\n      \n      <!-- AWWWARDS KINETIC INFINITE MARQUEE -->\n      <section class=\"kinetic-marquee-section\" aria-label=\"Highlights and Topics\">\n        <div class=\"marquee-track\">\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> AWS CLOUD INFRASTRUCTURE</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> GENERATIVE AI & AMAZON BEDROCK</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> 100% FREE COMMUNITY PASSES</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> SERVERLESS ARCHITECTURE</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> DEVSECOPS & CONTAINERS</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> LIVE HANDS-ON LABS</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> RUNGTA UNIVERSITY BHILAI</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> 22 AUGUST 2026</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> EXCLUSIVE SWAGS & MERCH</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> AWS CLOUD INFRASTRUCTURE</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> GENERATIVE AI & AMAZON BEDROCK</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> 100% FREE COMMUNITY PASSES</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> SERVERLESS ARCHITECTURE</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> DEVSECOPS & CONTAINERS</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> LIVE HANDS-ON LABS</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> RUNGTA UNIVERSITY BHILAI</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> 22 AUGUST 2026</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> EXCLUSIVE SWAGS & MERCH</span>\n        </div>\n        <div class=\"marquee-track marquee-track--reverse\">\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> DOCKER & KUBERNETES</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> PROMPT ENGINEERING</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> AWS LAMBDA & DYNAMODB</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> MICROSERVICES SCALING</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> STUDENT BUILDER HACKATHON</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> INDUSTRY MENTORSHIP</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> AWS CERTIFICATIONS ROADMAP</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> BUILD. LEARN. CONNECT.</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> DOCKER & KUBERNETES</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> PROMPT ENGINEERING</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> AWS LAMBDA & DYNAMODB</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> MICROSERVICES SCALING</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> STUDENT BUILDER HACKATHON</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> INDUSTRY MENTORSHIP</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> AWS CERTIFICATIONS ROADMAP</span>\n          <span class=\"marquee-tag\"><span class=\"star\">✦</span> BUILD. LEARN. CONNECT.</span>\n        </div>\n      </section>\n\n      <!-- ABOUT SECTION -->\n      <section id=\"about\" class=\"about-section\">\n        <div class=\"container\">\n          <div class=\"about__grid\">\n            <div class=\"about__text-col\">\n              <span class=\"about__tag\">✦ ABOUT THE EVENT ✦</span>\n              <h2 class=\"about__title\">A Day Built For The Next Generation Of Builders</h2>\n              <p class=\"about__desc\">\n                AWS Student Builder Community Day 2026 is an immersive, student-first cloud engineering conference engineered to inspire, educate, and connect the next wave of tech pioneers at Rungta University, Bhilai.\n              </p>\n              <p class=\"about__desc\" style=\"font-size:1rem;color:var(--color-text-secondary)\">\n                Whether you are writing your first line of serverless code or architecting complex microservices, this one-day conference offers expert keynotes, hands-on workshops, and direct access to industry mentors.\n              </p>\n              <div class=\"about__highlights\">\n                <div class=\"about__highlight-item\">\n                  <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"about__highlight-icon\"><path d=\"M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9Z\"></path></svg>\n                  <span>Cloud Computing</span>\n                </div>\n                <div class=\"about__highlight-item\">\n                  <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"about__highlight-icon\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"></rect><rect x=\"9\" y=\"9\" width=\"6\" height=\"6\"></rect><path d=\"M15 2v2\"></path><path d=\"M15 20v2\"></path><path d=\"M2 15h2\"></path><path d=\"M2 9h2\"></path><path d=\"M20 15h2\"></path><path d=\"M20 9h2\"></path><path d=\"M9 2v2\"></path><path d=\"M9 20v2\"></path></svg>\n                  <span>Artificial Intelligence</span>\n                </div>\n                <div class=\"about__highlight-item\">\n                  <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"about__highlight-icon\"><polyline points=\"4 17 10 11 4 5\"></polyline><line x1=\"12\" x2=\"20\" y1=\"19\" y2=\"19\"></line></svg>\n                  <span>DevOps & CI/CD</span>\n                </div>\n                <div class=\"about__highlight-item\">\n                  <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"about__highlight-icon\"><line x1=\"6\" x2=\"6\" y1=\"3\" y2=\"15\"></line><circle cx=\"18\" cy=\"6\" r=\"3\"></circle><circle cx=\"6\" cy=\"18\" r=\"3\"></circle><path d=\"M18 9a9 9 0 0 1-9 9\"></path></svg>\n                  <span>Open Source</span>\n                </div>\n                <div class=\"about__highlight-item\">\n                  <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"about__highlight-icon\"><circle cx=\"18\" cy=\"5\" r=\"3\"></circle><circle cx=\"6\" cy=\"12\" r=\"3\"></circle><circle cx=\"18\" cy=\"19\" r=\"3\"></circle><line x1=\"8.59\" x2=\"15.42\" y1=\"13.51\" y2=\"17.49\"></line><line x1=\"15.41\" x2=\"8.59\" y1=\"6.51\" y2=\"10.49\"></line></svg>\n                  <span>Networking</span>\n                </div>\n                <div class=\"about__highlight-item\">\n                  <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"about__highlight-icon\"><path d=\"M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5\"></path><path d=\"M9 18h6\"></path><path d=\"M10 22h4\"></path></svg>\n                  <span>Innovation</span>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"about__visual-card\">\n              <div class=\"about__visual-glow\"></div>\n              <div class=\"about__floating-badge hover-lift\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#0066CC\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9Z\"></path></svg>\n                <span>AWS Serverless Architecture</span>\n              </div>\n              <div class=\"about__floating-badge about__floating-badge--2 hover-lift\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#FF9900\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"></rect><rect x=\"9\" y=\"9\" width=\"6\" height=\"6\"></rect><path d=\"M15 2v2\"></path><path d=\"M15 20v2\"></path><path d=\"M2 15h2\"></path><path d=\"M2 9h2\"></path><path d=\"M20 15h2\"></path><path d=\"M20 9h2\"></path><path d=\"M9 2v2\"></path><path d=\"M9 20v2\"></path></svg>\n                <span>GenAI & Machine Learning</span>\n              </div>\n              <div class=\"about__floating-badge about__floating-badge--3 hover-lift\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#00F0FF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"4 17 10 11 4 5\"></polyline><line x1=\"12\" x2=\"20\" y1=\"19\" y2=\"19\"></line></svg>\n                <span>500+ Student Developers</span>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- EXPERIENCE (WHY) SECTION -->\n      <section id=\"experience\" class=\"why-section\">\n        <div class=\"container\">\n          <div class=\"why__header\">\n            <span class=\"caption\" style=\"color:var(--color-text-accent)\">✦ WHY YOU CANNOT MISS THIS ✦</span>\n            <h2 class=\"h2\">Engineered For Student Builders</h2>\n            <p class=\"body-md\">Everything you need to accelerate your cloud journey in one packed, action-oriented day.</p>\n          </div>\n\n          <div class=\"why__grid\">\n            <div class=\"why__card\">\n              <div class=\"why__icon-wrapper\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"></path><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"></path></svg>\n              </div>\n              <h3 class=\"why__card-title\">Learn</h3>\n              <p class=\"why__card-desc\">Deep-dive technical keynotes and breakout sessions led by cloud experts, mentors, and community leaders.</p>\n            </div>\n\n            <div class=\"why__card\">\n              <div class=\"why__icon-wrapper\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m18 16 4-4-4-4\"></path><path d=\"m6 8-4 4 4 4\"></path><path d=\"m14.5 4-5 16\"></path></svg>\n              </div>\n              <h3 class=\"why__card-title\">Build</h3>\n              <p class=\"why__card-desc\">Hands-on cloud architecture labs where you write code, deploy serverless functions, and solve real-world problems.</p>\n            </div>\n\n            <div class=\"why__card\">\n              <div class=\"why__icon-wrapper\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"></path><circle cx=\"9\" cy=\"7\" r=\"4\"></circle><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"></path><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"></path></svg>\n              </div>\n              <h3 class=\"why__card-title\">Connect</h3>\n              <p class=\"why__card-desc\">Network with 500+ passionate student developers, alumni, and industry mentors from across the region.</p>\n            </div>\n\n            <div class=\"why__card\">\n              <div class=\"why__icon-wrapper\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4.5 16.5c-1.5 1.26-2 5-2 5s3.74-.5 5-2c.71-.84.7-2.13-.09-2.91a2.18 2.18 0 0 0-2.91-.09z\"></path><path d=\"m12 15-3-3a22 22 0 0 1 2-3.95A12.88 12.88 0 0 1 22 2c0 2.72-.78 7.5-6 11a22.35 22.35 0 0 1-4 2z\"></path><path d=\"M9 12H4s.55-3.03 2-4c1.62-1.08 5 0 5 0\"></path><path d=\"M12 15v5s3.03-.55 4-2c1.08-1.62 0-5 0-5\"></path></svg>\n              </div>\n              <h3 class=\"why__card-title\">Innovate</h3>\n              <p class=\"why__card-desc\">Explore cutting-edge GenAI models, cloud DevOps pipelines, and student builder project showcases.</p>\n            </div>\n\n            <div class=\"why__card\">\n              <div class=\"why__icon-wrapper\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"22 7 13.5 15.5 8.5 10.5 2 17\"></polyline><polyline points=\"16 7 22 7 22 13\"></polyline></svg>\n              </div>\n              <h3 class=\"why__card-title\">Career Growth</h3>\n              <p class=\"why__card-desc\">Gain industry insights, cloud certification roadmaps, and career mentorship to accelerate your developer journey.</p>\n            </div>\n\n            <div class=\"why__card\">\n              <div class=\"why__icon-wrapper\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20\"></path><path d=\"M2 12h20\"></path></svg>\n              </div>\n              <h3 class=\"why__card-title\">Community</h3>\n              <p class=\"why__card-desc\">Join a vibrant open-source student ecosystem that builds, learns, and grows together long after the event ends.</p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- SCHEDULE TIMELINE SECTION -->\n      <section id=\"schedule\" class=\"timeline-section\">\n        <div class=\"container\">\n          <div class=\"timeline__header\">\n            <span class=\"caption\" style=\"color:var(--color-text-accent)\">✦ EVENT AGENDA ✦</span>\n            <h2 class=\"h2\">Event Timeline</h2>\n            <p class=\"body-md\">An action-packed day of keynotes, hands-on labs, networking, and live builder showcases.</p>\n          </div>\n\n          \n          <!-- INTERACTIVE SCHEDULE TRACK FILTERS (MOBBIN / COLLECT UI) -->\n          <div class=\"schedule-filters\" role=\"tablist\">\n            <button type=\"button\" class=\"schedule-filter-btn active\" data-filter=\"all\">All Sessions (8)</button>\n            <button type=\"button\" class=\"schedule-filter-btn\" data-filter=\"keynote\">Keynotes & Talks (2)</button>\n            <button type=\"button\" class=\"schedule-filter-btn\" data-filter=\"workshop\">Hands-on Labs (2)</button>\n            <button type=\"button\" class=\"schedule-filter-btn\" data-filter=\"social\">Networking & Contests (4)</button>\n          </div>\n\n          <div class=\"timeline__container\">\n            <div class=\"timeline__line\" aria-hidden=\"true\"></div>\n\n            <div class=\"timeline__item\">\n              <div class=\"timeline__node\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"></path><circle cx=\"9\" cy=\"7\" r=\"4\"></circle><polyline points=\"16 11 18 13 22 9\"></polyline></svg>\n              </div>\n              <div class=\"timeline__content\">\n                <div class=\"timeline__card\">\n                  <span class=\"timeline__time\">09:00 AM – 09:45 AM</span>\n                  <h3 class=\"timeline__title\">Registration & Welcome Swag Kit</h3>\n                  <p class=\"timeline__desc\">Check-in at the venue gate, scan your digital QR pass, receive exclusive AWS SBCD swag kits and badge passes.</p>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"timeline__item\">\n              <div class=\"timeline__node\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z\"></path><path d=\"M19 10v2a7 7 0 0 1-14 0v-2\"></path><line x1=\"12\" x2=\"12\" y1=\"19\" y2=\"22\"></line></svg>\n              </div>\n              <div class=\"timeline__content\">\n                <div class=\"timeline__card\">\n                  <span class=\"timeline__time\">09:45 AM – 11:00 AM</span>\n                  <h3 class=\"timeline__title\">Opening Keynote: Building in the Cloud Era</h3>\n                  <p class=\"timeline__desc\">Welcome address from campus leads and AWS community builders outlining the future of cloud engineering & GenAI.</p>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"timeline__item\">\n              <div class=\"timeline__node\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 16V7a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v9m16 0H4m16 0 1.28 2.55a1 1 0 0 1-.9 1.45H3.62a1 1 0 0 1-.9-1.45L4 16\"></path></svg>\n              </div>\n              <div class=\"timeline__content\">\n                <div class=\"timeline__card\">\n                  <span class=\"timeline__time\">11:00 AM – 12:30 PM</span>\n                  <h3 class=\"timeline__title\">Cloud Workshop: Hands-on Serverless & GenAI</h3>\n                  <p class=\"timeline__desc\">Interactive technical workshop guiding attendees through deploying live AWS Lambda functions and Bedrock AI endpoints.</p>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"timeline__item\">\n              <div class=\"timeline__node\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"></path><circle cx=\"9\" cy=\"7\" r=\"4\"></circle><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"></path><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"></path></svg>\n              </div>\n              <div class=\"timeline__content\">\n                <div class=\"timeline__card\">\n                  <span class=\"timeline__time\">12:30 PM – 01:15 PM</span>\n                  <h3 class=\"timeline__title\">Developer Networking & Community Lounge</h3>\n                  <p class=\"timeline__desc\">Connect with fellow student builders, mentors, speaker guests, and local user group leaders in the main atrium.</p>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"timeline__item\">\n              <div class=\"timeline__node\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 8h1a4 4 0 1 1 0 8h-1\"></path><path d=\"M3 8h14v9a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4Z\"></path><line x1=\"6\" x2=\"6\" y1=\"2\" y2=\"4\"></line><line x1=\"10\" x2=\"10\" y1=\"2\" y2=\"4\"></line><line x1=\"14\" x2=\"14\" y1=\"2\" y2=\"4\"></line></svg>\n              </div>\n              <div class=\"timeline__content\">\n                <div class=\"timeline__card\">\n                  <span class=\"timeline__time\">01:15 PM – 02:15 PM</span>\n                  <h3 class=\"timeline__title\">Lunch & Builder Social</h3>\n                  <p class=\"timeline__desc\">Networking lunch provided for all registered attendees. Informal discussions and project demonstrations.</p>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"timeline__item\">\n              <div class=\"timeline__node\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"></rect><rect x=\"9\" y=\"9\" width=\"6\" height=\"6\"></rect><path d=\"M15 2v2\"></path><path d=\"M15 20v2\"></path><path d=\"M2 15h2\"></path><path d=\"M2 9h2\"></path><path d=\"M20 15h2\"></path><path d=\"M20 9h2\"></path><path d=\"M9 2v2\"></path><path d=\"M9 20v2\"></path></svg>\n              </div>\n              <div class=\"timeline__content\">\n                <div class=\"timeline__card\">\n                  <span class=\"timeline__time\">02:15 PM – 03:45 PM</span>\n                  <h3 class=\"timeline__title\">Hands-on Lab: Deploying Microservices on AWS</h3>\n                  <p class=\"timeline__desc\">Step-by-step lab building resilient containerized backend microservices using AWS ECS, Fargate, and DynamoDB.</p>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"timeline__item\">\n              <div class=\"timeline__node\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"8\" r=\"6\"></circle><path d=\"M15.477 12.89 17 22l-5-3-5 3 1.523-9.11\"></path></svg>\n              </div>\n              <div class=\"timeline__content\">\n                <div class=\"timeline__card\">\n                  <span class=\"timeline__time\">03:45 PM – 04:30 PM</span>\n                  <h3 class=\"timeline__title\">Builder Challenge & Project Demos</h3>\n                  <p class=\"timeline__desc\">Fast-paced mini hackathon showcase where student builders pitch their cloud applications live on stage.</p>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"timeline__item\">\n              <div class=\"timeline__node\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z\"></path><line x1=\"4\" x2=\"4\" y1=\"22\" y2=\"15\"></line></svg>\n              </div>\n              <div class=\"timeline__content\">\n                <div class=\"timeline__card\">\n                  <span class=\"timeline__time\">04:30 PM – 05:00 PM</span>\n                  <h3 class=\"timeline__title\">Closing Ceremony & Swag Giveaway</h3>\n                  <p class=\"timeline__desc\">Closing remarks, recognition of top builder challenge teams, certificate distribution info, and community wrap-up.</p>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- COMMUNITY PHILOSOPHY SECTION -->\n      <section id=\"community\" class=\"community-section\">\n        <div class=\"container\">\n          <div class=\"community__grid\">\n            <div class=\"community__visual-box\">\n              <svg class=\"community__visual-svg\" viewBox=\"0 0 400 300\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n                <circle cx=\"200\" cy=\"150\" r=\"80\" stroke=\"#0066CC\" stroke-width=\"2\" stroke-dasharray=\"4 4\"></circle>\n                <circle cx=\"200\" cy=\"150\" r=\"120\" stroke=\"#00F0FF\" stroke-width=\"1\" opacity=\"0.4\"></circle>\n                <circle cx=\"200\" cy=\"150\" r=\"28\" fill=\"#111726\" stroke=\"#FF9900\" stroke-width=\"2\"></circle>\n                <text x=\"200\" y=\"154\" text-anchor=\"middle\" fill=\"#FF9900\" font-size=\"12\" font-family=\"monospace\" font-weight=\"bold\">AWS</text>\n                <g class=\"animate-fade-in\">\n                  <circle cx=\"120\" cy=\"90\" r=\"18\" fill=\"#111726\" stroke=\"#0066CC\" stroke-width=\"2\"></circle>\n                  <text x=\"120\" y=\"94\" text-anchor=\"middle\" fill=\"#F0F6FC\" font-size=\"10\" font-family=\"monospace\">BUILD</text>\n                  <circle cx=\"280\" cy=\"90\" r=\"18\" fill=\"#111726\" stroke=\"#00F0FF\" stroke-width=\"2\"></circle>\n                  <text x=\"280\" y=\"94\" text-anchor=\"middle\" fill=\"#F0F6FC\" font-size=\"10\" font-family=\"monospace\">LEARN</text>\n                  <circle cx=\"120\" cy=\"210\" r=\"18\" fill=\"#111726\" stroke=\"#00F0FF\" stroke-width=\"2\"></circle>\n                  <text x=\"120\" y=\"214\" text-anchor=\"middle\" fill=\"#F0F6FC\" font-size=\"10\" font-family=\"monospace\">SHARE</text>\n                  <circle cx=\"280\" cy=\"210\" r=\"18\" fill=\"#111726\" stroke=\"#0066CC\" stroke-width=\"2\"></circle>\n                  <text x=\"280\" y=\"214\" text-anchor=\"middle\" fill=\"#F0F6FC\" font-size=\"10\" font-family=\"monospace\">GROW</text>\n                </g>\n                <line x1=\"138\" y1=\"102\" x2=\"182\" y2=\"136\" stroke=\"#0066CC\" stroke-width=\"1.5\" opacity=\"0.6\"></line>\n                <line x1=\"262\" y1=\"102\" x2=\"218\" y2=\"136\" stroke=\"#00F0FF\" stroke-width=\"1.5\" opacity=\"0.6\"></line>\n                <line x1=\"138\" y1=\"198\" x2=\"182\" y2=\"164\" stroke=\"#00F0FF\" stroke-width=\"1.5\" opacity=\"0.6\"></line>\n                <line x1=\"262\" y1=\"198\" x2=\"218\" y2=\"164\" stroke=\"#0066CC\" stroke-width=\"1.5\" opacity=\"0.6\"></line>\n              </svg>\n            </div>\n\n            <div class=\"community__text-box\">\n              <span class=\"caption\" style=\"color:var(--color-text-accent)\">✦ COMMUNITY PHILOSOPHY ✦</span>\n              <h2 class=\"h2\">Builders Build The Future.</h2>\n              <p class=\"body-lg\">We believe the most effective way to master cloud engineering is by building real projects alongside a passionate peer network.</p>\n              <div class=\"community__quote\">\n                \"Technology is at its best when it brings student builders together to solve real problems through open-source code and cloud innovation.\"\n              </div>\n              <p class=\"body-md\" style=\"color:var(--color-text-secondary)\">\n                The AWS Student Builder Community is created by students, for students. From university classrooms to global cloud architectures, we empower every builder with tools, guidance, and opportunity.\n              </p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- VENUE SECTION -->\n      <section id=\"venue\" class=\"venue-section\">\n        <div class=\"container\">\n          <div class=\"venue__grid\">\n            <div>\n              <span class=\"caption\" style=\"color:var(--color-text-accent)\">✦ HOST VENUE ✦</span>\n              <h2 class=\"h2\" style=\"margin-top:0.5rem;margin-bottom:1rem\">Rungta University, Bhilai</h2>\n              <p class=\"body-lg\" style=\"margin-bottom:1rem\">\n                A premier institution for technical education and research innovation in Chhattisgarh, providing state-of-the-art auditoriums, computing labs, and high-speed Wi-Fi infrastructure.\n              </p>\n              <p class=\"body-md\" style=\"color:var(--color-text-secondary); margin-bottom: 1.5rem;\">\n                Located in Bhilai, the educational hub of Chhattisgarh, Rungta University fosters an active developer ecosystem with dedicated student clubs, hackathons, and technology incubators.\n              </p>\n              <a href=\"https://maps.app.goo.gl/J7DvAnneeEWmdWRQ8\" target=\"_blank\" class=\"btn btn--secondary\" style=\"font-size:0.9rem;\">\n                <span>Open Location in Google Maps ↗</span>\n              </a>\n            </div>\n\n            <div class=\"venue__card\">\n              <div class=\"venue__card-badge\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z\"></path><circle cx=\"12\" cy=\"10\" r=\"3\"></circle></svg>\n                <span>Bhilai, Chhattisgarh, India</span>\n              </div>\n              <div>\n                <h3 class=\"h3\" style=\"color:var(--color-text-primary)\">Main Campus Auditorium</h3>\n                <p class=\"body-sm\" style=\"color:var(--color-text-secondary);margin-top:0.25rem\">\n                  Equipped with dual HD projection screens, surround audio, high-density seating for 500+ attendees, and dedicated workshop lab spaces.\n                </p>\n              </div>\n              <div class=\"venue__stats-row\">\n                <div class=\"venue__stat-item\">\n                  <span class=\"venue__stat-num\">500+</span>\n                  <span class=\"venue__stat-lbl\">Seating Capacity</span>\n                </div>\n                <div class=\"venue__stat-item\">\n                  <span class=\"venue__stat-num\">1 Gbps</span>\n                  <span class=\"venue__stat-lbl\">Campus Fiber Network</span>\n                </div>\n                <div class=\"venue__stat-item\">\n                  <span class=\"venue__stat-num\">100%</span>\n                  <span class=\"venue__stat-lbl\">Free Registration</span>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- SPONSORS / ECOSYSTEM PARTNERS SECTION -->\n      <section class=\"sponsors-section\">\n        <div class=\"container\">\n          <div class=\"sponsors__header\">\n            <span class=\"caption\" style=\"color:var(--color-text-accent)\">✦ ECOSYSTEM PARTNERS ✦</span>\n            <h2 class=\"h3\" style=\"margin-top:0.5rem;color:var(--color-text-secondary)\">Supported By Community & Cloud Ecosystem Pioneers</h2>\n          </div>\n          <div class=\"sponsors__grid\">\n            <div class=\"sponsors__card\">\n              <span class=\"sponsors__logo-text\">AWS</span>\n              <span class=\"sponsors__tier\">Title Sponsor</span>\n            </div>\n            <div class=\"sponsors__card\">\n              <span class=\"sponsors__logo-text\">GitHub</span>\n              <span class=\"sponsors__tier\">Community Partner</span>\n            </div>\n            <div class=\"sponsors__card\">\n              <span class=\"sponsors__logo-text\">Microsoft</span>\n              <span class=\"sponsors__tier\">Ecosystem Partner</span>\n            </div>\n            <div class=\"sponsors__card\">\n              <span class=\"sponsors__logo-text\">Google Cloud</span>\n              <span class=\"sponsors__tier\">Tech Sponsor</span>\n            </div>\n            <div class=\"sponsors__card\">\n              <span class=\"sponsors__logo-text\">MongoDB</span>\n              <span class=\"sponsors__tier\">Data Partner</span>\n            </div>\n            <div class=\"sponsors__card\">\n              <span class=\"sponsors__logo-text\">Vercel</span>\n              <span class=\"sponsors__tier\">Deployment Partner</span>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- TESTIMONIALS SECTION -->\n      <section class=\"testimonials-section\">\n        <div class=\"container\">\n          <div class=\"testimonials__header\">\n            <span class=\"caption\" style=\"color:var(--color-text-accent)\">✦ BUILDER STORIES ✦</span>\n            <h2 class=\"h2\">Loved By Student Builders</h2>\n            <p class=\"body-md\">Hear from previous student attendees who accelerated their cloud learning journey.</p>\n          </div>\n\n          <div class=\"testimonials__grid\">\n            <div class=\"testimonials__card\">\n              <div>\n                <div style=\"display:flex;gap:0.25rem;color:var(--color-aws-amber);margin-bottom:1rem\">\n                  ★★★★★\n                </div>\n                <p class=\"testimonials__text\">\n                  \"Attending the AWS Student Builder event changed how I think about cloud architecture. The hands-on labs helped me deploy my first production serverless app!\"\n                </p>\n              </div>\n              <div class=\"testimonials__author\">\n                <div class=\"testimonials__avatar\">AK</div>\n                <div>\n                  <h4 class=\"testimonials__name\">Aditya Kumar</h4>\n                  <span class=\"testimonials__role\">3rd Year B.Tech CSE • Rungta College</span>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"testimonials__card\">\n              <div>\n                <div style=\"display:flex;gap:0.25rem;color:var(--color-aws-amber);margin-bottom:1rem\">\n                  ★★★★★\n                </div>\n                <p class=\"testimonials__text\">\n                  \"The networking opportunities were top-tier. I connected with campus mentors and got guidance on preparing for AWS Certified Cloud Practitioner.\"\n                </p>\n              </div>\n              <div class=\"testimonials__author\">\n                <div class=\"testimonials__avatar\">SP</div>\n                <div>\n                  <h4 class=\"testimonials__name\">Sneha Patel</h4>\n                  <span class=\"testimonials__role\">4th Year IT • BIT Durg</span>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"testimonials__card\">\n              <div>\n                <div style=\"display:flex;gap:0.25rem;color:var(--color-aws-amber);margin-bottom:1rem\">\n                  ★★★★★\n                </div>\n                <p class=\"testimonials__text\">\n                  \"Submitting our project in the builder challenge was an incredible experience. The community energy is unmatched for student developers!\"\n                </p>\n              </div>\n              <div class=\"testimonials__author\">\n                <div class=\"testimonials__avatar\">RS</div>\n                <div>\n                  <h4 class=\"testimonials__name\">Rohan Sharma</h4>\n                  <span class=\"testimonials__role\">2nd Year AI & ML • NIT Raipur</span>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- FAQ SECTION -->\n      <section id=\"faq\" class=\"faq-section\">\n        <div class=\"container\">\n          <div class=\"faq__header\">\n            <span class=\"caption\" style=\"color:var(--color-text-accent)\">✦ FREQUENTLY ASKED QUESTIONS ✦</span>\n            <h2 class=\"h2\">Got Questions? We Have Answers.</h2>\n            <p class=\"body-md\">Everything you need to know about AWS Student Builder Community Day 2026.</p>\n          </div>\n\n          <div class=\"faq__container\">\n            <div class=\"faq__item\">\n              <button type=\"button\" class=\"faq__trigger\" aria-expanded=\"false\">\n                <span>Who can attend?</span>\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"faq__icon\"><path d=\"m6 9 6 6 6-6\"></path></svg>\n              </button>\n              <div class=\"faq__content\" style=\"display:none;\">\n                Any college or university student, developer, or tech enthusiast can attend. All academic years (1st to 4th year) and all branches are warmly welcomed.\n              </div>\n            </div>\n\n            <div class=\"faq__item\">\n              <button type=\"button\" class=\"faq__trigger\" aria-expanded=\"false\">\n                <span>Is registration free?</span>\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"faq__icon\"><path d=\"m6 9 6 6 6-6\"></path></svg>\n              </button>\n              <div class=\"faq__content\" style=\"display:none;\">\n                Yes, 100% free! There are zero registration fees. All keynotes, labs, swag kits, and event access are completely complimentary.\n              </div>\n            </div>\n\n            <div class=\"faq__item\">\n              <button type=\"button\" class=\"faq__trigger\" aria-expanded=\"false\">\n                <span>Do beginners need prior cloud experience?</span>\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"faq__icon\"><path d=\"m6 9 6 6 6-6\"></path></svg>\n              </button>\n              <div class=\"faq__content\" style=\"display:none;\">\n                No prior cloud experience is required. Sessions range from foundational cloud engineering to hands-on serverless labs with step-by-step mentor guidance.\n              </div>\n            </div>\n\n            <div class=\"faq__item\">\n              <button type=\"button\" class=\"faq__trigger\" aria-expanded=\"false\">\n                <span>Will certificates be provided?</span>\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"faq__icon\"><path d=\"m6 9 6 6 6-6\"></path></svg>\n              </button>\n              <div class=\"faq__content\" style=\"display:none;\">\n                Yes, an official verified Digital Certificate of Attendance will be issued to all participants who check in at the venue.\n              </div>\n            </div>\n\n            <div class=\"faq__item\">\n              <button type=\"button\" class=\"faq__trigger\" aria-expanded=\"false\">\n                <span>How do I register?</span>\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"faq__icon\"><path d=\"m6 9 6 6 6-6\"></path></svg>\n              </button>\n              <div class=\"faq__content\" style=\"display:none;\">\n                Click any \"Register Now\" button, fill in your details (name, email, phone, branch, year), and your pass will be generated instantly and sent to your WhatsApp.\n              </div>\n            </div>\n\n            <div class=\"faq__item\">\n              <button type=\"button\" class=\"faq__trigger\" aria-expanded=\"false\">\n                <span>What should I bring to the venue?</span>\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"faq__icon\"><path d=\"m6 9 6 6 6-6\"></path></svg>\n              </button>\n              <div class=\"faq__content\" style=\"display:none;\">\n                Please bring your college student ID card, your digital entry pass on your phone, and your laptop with charger for the hands-on serverless labs.\n              </div>\n            </div>\n\n            <div class=\"faq__item\">\n              <button type=\"button\" class=\"faq__trigger\" aria-expanded=\"false\">\n                <span>Can I cancel or update my registration?</span>\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"faq__icon\"><path d=\"m6 9 6 6 6-6\"></path></svg>\n              </button>\n              <div class=\"faq__content\" style=\"display:none;\">\n                Yes, you can contact the organizing team directly via the WhatsApp support link if you need any changes or assistance.\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- CTA BANNER SECTION -->\n      <section class=\"cta-section\" id=\"register-cta\">\n        <div class=\"container\">\n          <div class=\"cta__card\">\n            <div class=\"cta__glow\" aria-hidden=\"true\"></div>\n            <div style=\"display:inline-flex;align-items:center;gap:0.5rem;color:var(--color-aws-amber);font-family:var(--font-jetbrains);font-size:0.875rem\">\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m12 3-1.912 5.813a2 2 0 0 1-1.275 1.275L3 12l5.813 1.912a2 2 0 0 1 1.275 1.275L12 21l1.912-5.813a2 2 0 0 1 1.275-1.275L21 12l-5.813-1.912a2 2 0 0 1-1.275-1.275L12 3Z\"></path><path d=\"M5 3v4\"></path><path d=\"M19 17v4\"></path><path d=\"M3 5h4\"></path><path d=\"M17 19h4\"></path></svg>\n              <span>LIMITED TO 500+ ATTENDEES</span>\n            </div>\n            <h2 class=\"cta__title\">Ready To Build The Future?</h2>\n            <p class=\"cta__desc\">Join 500+ student builders at Rungta University, Bhilai on 22 August 2026. Claim your free digital pass today.</p>\n            <button type=\"button\" class=\"btn btn--primary btn--lg\" id=\"ctaRegBtn\" style=\"font-size:1.125rem;padding:1rem 2.25rem\">\n              <span>Claim Free Pass Now</span>\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12h14\"></path><path d=\"m12 5 7 7-7 7\"></path></svg>\n            </button>\n          </div>\n        </div>\n      </section>\n\n      \n\n    </main>\n\n    <!-- FOOTER -->\n    <footer class=\"footer\">\n      <div class=\"container\">\n        <div class=\"footer__grid\">\n          <div class=\"footer__brand-col\">\n            <div class=\"footer__logo\">\n              <img alt=\"AWS SBCD Logo\" width=\"26\" height=\"26\" style=\"border-radius:6px;object-fit:cover\" src=\"images/logo.png\" onerror=\"this.src='public/images/logo.png'\"/>\n              <span>AWS SBCD 2026</span>\n            </div>\n            <p class=\"footer__desc\">\n              Building the future of cloud engineering. Join 500+ student builders, developers, and tech pioneers at Rungta University, Bhilai.\n            </p>\n            <div class=\"footer__socials\">\n              <a href=\"https://github.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"footer__social-btn\" aria-label=\"GitHub\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 22v-4a4.8 4.8 0 0 0-1-3.5c3 0 6-2 6-5.5.08-1.25-.27-2.48-1-3.5.28-1.15.28-2.35 0-3.5 0 0-1 0-3 1.5-2.64-.5-5.36-.5-8 0C6 2 5 2 5 2c-.3 1.15-.3 2.35 0 3.5A5.403 5.403 0 0 0 4 9c0 3.5 3 5.5 6 5.5-.39.49-.68 1.05-.85 1.65-.17.6-.22 1.23-.15 1.85v4\"></path><path d=\"M9 18c-4.51 2-5-2-7-2\"></path></svg>\n              </a>\n              <a href=\"https://linkedin.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"footer__social-btn\" aria-label=\"LinkedIn\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 8a6 6 0 0 1 6 6v7h-4v-7a2 2 0 0 0-2-2 2 2 0 0 0-2 2v7h-4v-7a6 6 0 0 1 6-6z\"></path><rect width=\"4\" height=\"12\" x=\"2\" y=\"9\"></rect><circle cx=\"4\" cy=\"4\" r=\"2\"></circle></svg>\n              </a>\n              <a href=\"https://x.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"footer__social-btn\" aria-label=\"Twitter\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 4s-.7 2.1-2 3.4c1.6 10-9.4 17.3-18 11.6 2.2.1 4.4-.6 6-2C3 15.5.5 9.6 3 5c2.2 2.6 5.6 4.1 9 4-.9-4.2 4-6.6 7-3.8 1.1 0 3-1.2 3-1.2z\"></path></svg>\n              </a>\n              <a href=\"https://youtube.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"footer__social-btn\" aria-label=\"YouTube\">\n                <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2.5 17a24.12 24.12 0 0 1 0-10 2 2 0 0 1 1.4-1.4 49.56 49.56 0 0 1 16.2 0A2 2 0 0 1 21.5 7a24.12 24.12 0 0 1 0 10 2 2 0 0 1-1.4 1.4 49.55 49.55 0 0 1-16.2 0A2 2 0 0 1 2.5 17\"></path><path d=\"m10 15 5-3-5-3z\"></path></svg>\n              </a>\n            </div>\n          </div>\n\n          <div>\n            <h4 class=\"footer__col-title\">Navigation</h4>\n            <ul class=\"footer__links\">\n              <li><a href=\"#experience\" class=\"footer__link\">Experience</a></li>\n              <li><a href=\"#schedule\" class=\"footer__link\">Schedule</a></li>\n              <li><a href=\"#community\" class=\"footer__link\">Community</a></li>\n              <li><a href=\"#faq\" class=\"footer__link\">FAQ</a></li>\n              <li><a href=\"admin.html\" class=\"footer__link\" style=\"color:var(--color-text-accent)\">⚡ Admin Console</a></li>\n            </ul>\n          </div>\n\n          <div>\n            <h4 class=\"footer__col-title\">Event Info</h4>\n            <ul class=\"footer__links\">\n              <li class=\"footer__link\">📅 22 August 2026</li>\n              <li class=\"footer__link\">📍 Rungta University, Bhilai, CG</li>\n              <li class=\"footer__link\">🎟️ 100% Free</li>\n              <li class=\"footer__link\">👥 500+ Builders</li>\n            </ul>\n          </div>\n        </div>\n\n        <div class=\"footer__disclaimer\">\n          <strong>LEGAL DISCLAIMER:</strong> This is a community-driven initiative organized by AWS Student Builders at Rungta University.\n        </div>\n\n        <div class=\"footer__bottom\" style=\"flex-direction:column;gap:1rem;align-items:center\">\n          <div style=\"display:flex;width:100%;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:1rem;padding-top:0.75rem\">\n            <span>© 2026 AWS Student Builder Community Day • Rungta University. All rights reserved.</span>\n            <button type=\"button\" class=\"footer__social-btn\" id=\"backToTopBtn\" style=\"width:auto;padding:0 0.875rem;gap:0.5rem\" aria-label=\"Scroll back to top\">\n              <span>Back to Top</span>\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m5 12 7-7 7 7\"></path><path d=\"M12 19V5\"></path></svg>\n            </button>\n          </div>\n        </div>\n      </div>\n    </footer>\n\n  </div>\n\n  <!-- REGISTRATION MODAL (HIGH FIDELITY) -->\n  <div class=\"reg-modal-overlay\" id=\"regModal\">\n    <div class=\"reg-modal-card\">\n      <button class=\"modal-close-btn\" id=\"closeModalBtn\" aria-label=\"Close modal\">&times;</button>\n      \n      <div id=\"formView\">\n        <span class=\"modal-step-badge\">🎟️ OFFICIAL STUDENT REGISTRATION</span>\n        <h2 style=\"font-size: 1.5rem; font-weight: 800; margin-bottom: 0.4rem;\">Claim Your Free Pass</h2>\n        <p style=\"color: var(--color-text-secondary); font-size: 0.875rem; margin-bottom: 1.5rem;\">\n          Fill your official student details to reserve your seat at Rungta University, Bhilai on 22 August 2026.\n        </p>\n\n        <form id=\"studentRegistrationForm\">\n          <div class=\"reg-form-group\">\n            <label for=\"regName\">FULL NAME <span class=\"req\">*</span></label>\n            <input type=\"text\" id=\"regName\" class=\"reg-input\" placeholder=\"e.g. Rahul Sharma\" required autofocus>\n          </div>\n\n          <div class=\"reg-grid-2\">\n            <div class=\"reg-form-group\">\n              <label for=\"regEmail\">EMAIL ADDRESS <span class=\"req\">*</span></label>\n              <input type=\"email\" id=\"regEmail\" class=\"reg-input\" placeholder=\"student@rungta.ac.in\" required>\n            </div>\n            <div class=\"reg-form-group\">\n              <label for=\"regPhone\">PHONE NUMBER <span class=\"req\">*</span></label>\n              <input type=\"tel\" id=\"regPhone\" pattern=\"[0-9]{10}\" class=\"reg-input\" placeholder=\"10-digit mobile\" required>\n            </div>\n          </div>\n\n          <div class=\"reg-grid-2\">\n            <div class=\"reg-form-group\">\n              <label for=\"regBranch\">BRANCH <span class=\"req\">*</span></label>\n              <input type=\"text\" id=\"regBranch\" class=\"reg-input\" placeholder=\"e.g. CSE, IT, AIML\" required>\n            </div>\n            <div class=\"reg-form-group\">\n              <label for=\"regYear\">YEAR & SECTION <span class=\"req\">*</span></label>\n              <input type=\"text\" id=\"regYear\" class=\"reg-input\" placeholder=\"e.g. 3rd Year / Sec A\" required>\n            </div>\n          </div>\n\n          <button type=\"submit\" class=\"btn btn--primary\" id=\"submitRegBtn\" style=\"width:100%; justify-content:center; padding:0.9rem; font-size:1rem; margin-top:0.5rem;\">\n            <span>Generate Entry Pass & Send to WhatsApp &rarr;</span>\n          </button>\n        </form>\n      </div>\n\n      <!-- CONFIRMED PASS VIEW -->\n      <div id=\"passSuccessView\" style=\"display:none; text-align:center;\">\n        <span class=\"modal-step-badge\" style=\"background:rgba(35,134,54,0.15); border-color:#238636; color:#3fb950;\">\n          ✅ REGISTRATION CONFIRMED\n        </span>\n        <h2 style=\"font-size: 1.4rem; font-weight: 800; margin-bottom: 0.25rem;\">You're Ready to Build!</h2>\n        <p style=\"color: var(--color-text-secondary); font-size: 0.85rem;\">\n          Your official digital pass has been generated. Details sent to WhatsApp!\n        </p>\n\n        \n        <div class=\"hologram-pass tilt-card\" id=\"hologramTicket\">\n          <div class=\"hologram-pass-inner\">\n            <div class=\"hologram-watermark\">AWS</div>\n            <div class=\"pass-ticket-header\">\n              <div>\n                <span class=\"modal-step-badge\">CONFIRMED ATTENDEE PASS</span>\n                <div style=\"font-size:0.75rem;color:var(--color-text-secondary);margin-top:0.25rem;\">AWS Student Builder Community Day '26</div>\n              </div>\n              <div class=\"ticket-id-tag\" id=\"ticketPassId\">#AWS-RU-0000</div>\n            </div>\n\n            <div class=\"ticket-grid\">\n              <div class=\"ticket-grid-item\">\n                <label>ATTENDEE NAME</label>\n                <div id=\"ticketName\">---</div>\n              </div>\n              <div class=\"ticket-grid-item\">\n                <label>DEPARTMENT / BRANCH</label>\n                <div id=\"ticketBranch\">---</div>\n              </div>\n              <div class=\"ticket-grid-item\">\n                <label>YEAR / ACADEMIC SEC</label>\n                <div id=\"ticketYear\">---</div>\n              </div>\n              <div class=\"ticket-grid-item\">\n                <label>REGISTERED PHONE</label>\n                <div id=\"ticketPhone\">---</div>\n              </div>\n            </div>\n\n            <!-- Dynamic Barcode with Laser Beam Animation -->\n            <div class=\"barcode-scanner-box\">\n              <div class=\"laser-scan-line\"></div>\n              <div class=\"barcode-stripes\"></div>\n              <div style=\"font-family:var(--font-jetbrains);font-size:0.7rem;color:#64748b;letter-spacing:0.15em;\">SECURE ENTRY VERIFIED</div>\n            </div>\n\n            <div style=\"font-size:0.78rem; color:var(--color-text-muted); border-top:1px dashed rgba(255,255,255,0.1); padding-top:0.75rem; text-align:left;\">\n              📍 Rungta University Campus Auditorium, Bhilai • 22 August 2026 • 9:00 AM IST\n            </div>\n          </div>\n        </div>\n\n        <div class=\"ticket-actions\">\n          <a href=\"#\" target=\"_blank\" class=\"btn-wa-direct\" id=\"openWhatsAppBtn\">\n            <span>💬</span> Send Ticket Details to WhatsApp\n          </a>\n\n          <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:0.75rem;\">\n            <button type=\"button\" class=\"btn-ticket-secondary\" id=\"copyPassTextBtn\">\n              <span>📋 Copy Pass ID</span>\n            </button>\n            <button type=\"button\" class=\"btn-ticket-secondary\" id=\"printTicketBtn\">\n              <span>🖨️ Print Ticket</span>\n            </button>\n          </div>\n\n          <button type=\"button\" class=\"btn-ticket-secondary\" id=\"registerAnotherStudentBtn\" style=\"border-color:transparent;color:#94a3b8;\">\n            <span>&larr; Register Another Student</span>\n          </button>\n        </div>\n\n      </div>\n    </div>\n  </div>\n\n  <!-- CLIENT-SIDE INTERACTIVITY SCRIPTS -->\n  <script>\n    const ADMIN_PHONE = '919343756202';\n    const GOOGLE_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbz2nqsYrezuQ-FTOGoQQbDKpdEZW8ZPSLGx5YZzUhe29650r0Jb9ABoNWRVndstq-JJ/exec';\n\n    // 1. Scroll Progress & Sticky Navbar\n    window.addEventListener('scroll', () => {\n      const winScroll = document.documentElement.scrollTop;\n      const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;\n      const scrolled = height > 0 ? (winScroll / height) : 0;\n      document.getElementById('scrollProgressBar').style.transform = `scaleX(${scrolled})`;\n\n      const nav = document.getElementById('navbar');\n      if (winScroll > 40) {\n        nav.classList.add('navbar--scrolled');\n      } else {\n        nav.classList.remove('navbar--scrolled');\n      }\n    });\n\n    // 2. Countdown Timer (22 August 2026)\n    function initCountdown() {\n      const targetDate = new Date('2026-08-22T09:00:00+05:30').getTime();\n      function update() {\n        const now = new Date().getTime();\n        const diff = targetDate - now;\n        if (diff <= 0) {\n          document.getElementById('cdDays').textContent = '00';\n          document.getElementById('cdHours').textContent = '00';\n          document.getElementById('cdMinutes').textContent = '00';\n          document.getElementById('cdSeconds').textContent = '00';\n          return;\n        }\n        const d = Math.floor(diff / (1000 * 60 * 60 * 24));\n        const h = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));\n        const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));\n        const s = Math.floor((diff % (1000 * 60)) / 1000);\n\n        document.getElementById('cdDays').textContent = String(d).padStart(2, '0');\n        document.getElementById('cdHours').textContent = String(h).padStart(2, '0');\n        document.getElementById('cdMinutes').textContent = String(m).padStart(2, '0');\n        document.getElementById('cdSeconds').textContent = String(s).padStart(2, '0');\n      }\n      update();\n      setInterval(update, 1000);\n    }\n    initCountdown();\n\n    // 3. Interactive Constellation Canvas\n    const canvas = document.getElementById('cloudCanvas');\n    if (canvas) {\n      const ctx = canvas.getContext('2d');\n      let width = canvas.width = canvas.offsetWidth;\n      let height = canvas.height = canvas.offsetHeight;\n\n      window.addEventListener('resize', () => {\n        width = canvas.width = canvas.offsetWidth;\n        height = canvas.height = canvas.offsetHeight;\n      });\n\n      const nodes = [];\n      const labels = ['STUDENT', 'CODE', 'CLOUD', 'COMMUNITY', 'INNOVATION'];\n      const totalNodes = 32;\n\n      for (let i = 0; i < totalNodes; i++) {\n        nodes.push({\n          x: Math.random() * width,\n          y: Math.random() * height,\n          vx: (Math.random() - 0.5) * 0.4,\n          vy: (Math.random() - 0.5) * 0.4,\n          radius: Math.random() * 2.5 + 1.5,\n          color: i % 3 === 0 ? '#00F0FF' : (i % 3 === 1 ? '#0066CC' : '#FF9900'),\n          label: i < labels.length ? labels[i] : null\n        });\n      }\n\n      function drawConstellation() {\n        ctx.clearRect(0, 0, width, height);\n\n        // Draw connections\n        for (let i = 0; i < nodes.length; i++) {\n          for (let j = i + 1; j < nodes.length; j++) {\n            const dx = nodes[i].x - nodes[j].x;\n            const dy = nodes[i].y - nodes[j].y;\n            const dist = Math.sqrt(dx * dx + dy * dy);\n\n            if (dist < 140) {\n              ctx.beginPath();\n              ctx.moveTo(nodes[i].x, nodes[i].y);\n              ctx.lineTo(nodes[j].x, nodes[j].y);\n              ctx.strokeStyle = `rgba(124, 58, 237, ${0.2 * (1 - dist / 140)})`;\n              ctx.lineWidth = 0.8;\n              ctx.stroke();\n            }\n          }\n        }\n\n        // Draw nodes\n        nodes.forEach(node => {\n          node.x += node.vx;\n          node.y += node.vy;\n\n          if (node.x < 0 || node.x > width) node.vx *= -1;\n          if (node.y < 0 || node.y > height) node.vy *= -1;\n\n          ctx.beginPath();\n          ctx.arc(node.x, node.y, node.radius, 0, Math.PI * 2);\n          ctx.fillStyle = node.color;\n          ctx.shadowBlur = 8;\n          ctx.shadowColor = node.color;\n          ctx.fill();\n          ctx.shadowBlur = 0;\n\n          if (node.label) {\n            ctx.font = '10px JetBrains Mono, monospace';\n            ctx.fillStyle = 'rgba(240, 246, 252, 0.65)';\n            ctx.fillText(node.label, node.x + 8, node.y + 3);\n          }\n        });\n\n        requestAnimationFrame(drawConstellation);\n      }\n      drawConstellation();\n    }\n\n    // 4. FAQ Accordion\n    document.querySelectorAll('.faq__trigger').forEach(trigger => {\n      trigger.addEventListener('click', () => {\n        const item = trigger.closest('.faq__item');\n        const content = item.querySelector('.faq__content');\n        const isOpen = item.classList.contains('faq__item--open');\n\n        // Close other items\n        document.querySelectorAll('.faq__item').forEach(other => {\n          other.classList.remove('faq__item--open');\n          const oc = other.querySelector('.faq__content');\n          if (oc) oc.style.display = 'none';\n        });\n\n        if (!isOpen) {\n          item.classList.add('faq__item--open');\n          content.style.display = 'block';\n        }\n      });\n    });\n\n    // 5. Registration Modal Management\n    const regModal = document.getElementById('regModal');\n    const formView = document.getElementById('formView');\n    const passSuccessView = document.getElementById('passSuccessView');\n    const regForm = document.getElementById('studentRegistrationForm');\n    let lastGeneratedWhatsAppText = '';\n\n    function openRegistrationModal() {\n      formView.style.display = 'block';\n      passSuccessView.style.display = 'none';\n      regModal.classList.add('active');\n    }\n\n    function closeRegistrationModal() {\n      regModal.classList.remove('active');\n    }\n\n    document.getElementById('navRegBtn').addEventListener('click', openRegistrationModal);\n    document.getElementById('heroRegBtn').addEventListener('click', openRegistrationModal);\n    document.getElementById('ctaRegBtn').addEventListener('click', openRegistrationModal);\n    document.getElementById('closeModalBtn').addEventListener('click', closeRegistrationModal);\n    \n    window.addEventListener('click', (e) => {\n      if (e.target === regModal) closeRegistrationModal();\n    });\n\n    document.getElementById('registerAnotherStudentBtn').addEventListener('click', () => {\n      regForm.reset();\n      formView.style.display = 'block';\n      passSuccessView.style.display = 'none';\n    });\n\n    // 6. Form Submission & Ticket Generation (Direct Google Sheet + Local Server Dual Sync)\n    regForm.addEventListener('submit', async (e) => {\n      e.preventDefault();\n      const submitBtn = document.getElementById('submitRegBtn');\n      const originalText = submitBtn.innerHTML;\n      submitBtn.disabled = true;\n      submitBtn.innerHTML = 'GENERATING PASS... ⏳';\n\n      const randomSuffix = Math.floor(1000 + Math.random() * 9000);\n      const passId = `AWS-RU-${randomSuffix}`;\n      const now = new Date();\n      const formattedDate = now.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' });\n\n      const studentData = {\n        id: passId,\n        name: document.getElementById('regName').value.trim(),\n        email: document.getElementById('regEmail').value.trim(),\n        phone: document.getElementById('regPhone').value.trim(),\n        branch: document.getElementById('regBranch').value.trim(),\n        year: document.getElementById('regYear').value.trim(),\n        section: 'A',\n        registeredAt: now.toISOString(),\n        formattedDate: formattedDate\n      };\n\n      // 1. Direct real-time sync to Google Sheet (Spreadsheet backend)\n      const googleSheetSync = fetch(GOOGLE_SCRIPT_URL, {\n        method: 'POST',\n        headers: { 'Content-Type': 'text/plain;charset=utf-8' },\n        body: JSON.stringify(studentData)\n      }).catch(err => console.warn('Google Sheet background sync warning:', err));\n\n      // 2. Also persist to local Node / Vercel API backend if available\n      const localApiSync = fetch('/api/register', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(studentData)\n      }).then(r => r.ok ? r.json() : null).catch(() => null);\n\n      try {\n        // Run both syncs in parallel\n        await Promise.allSettled([googleSheetSync, localApiSync]);\n\n        // Cache in browser local storage\n        const list = JSON.parse(localStorage.getItem('aws_registrations_cache') || '[]');\n        list.unshift(studentData);\n        localStorage.setItem('aws_registrations_cache', JSON.stringify(list));\n\n        const waText = `🚀 *NEW REGISTRATION — AWS COMMUNITY DAY* 🚀\\n` +\n          `━━━━━━━━━━━━━━━━━━━━\\n` +\n          `🎟️ *Pass ID*: #${passId}\\n` +\n          `👤 *Student Name*: ${studentData.name}\\n` +\n          `📱 *Mobile*: ${studentData.phone}\\n` +\n          `📧 *Email*: ${studentData.email}\\n` +\n          `🎓 *Branch*: ${studentData.branch}\\n` +\n          `📅 *Year / Sec*: ${studentData.year}\\n` +\n          `🏛️ *Venue*: Rungta University Campus, Bhilai\\n` +\n          `⏰ *Registered On*: ${formattedDate}\\n` +\n          `━━━━━━━━━━━━━━━━━━━━\\n` +\n          `✅ *Status*: Confirmed Student Pass`;\n\n        showSuccessPass({\n          registration: studentData,\n          whatsappText: waText,\n          adminWhatsAppUrl: `https://wa.me/${ADMIN_PHONE}?text=${encodeURIComponent(waText)}`\n        });\n      } catch (err) {\n        console.error('Registration processing error:', err);\n      } finally {\n        submitBtn.disabled = false;\n        submitBtn.innerHTML = originalText;\n      }\n    });\n\n    function showSuccessPass(data) {\n      const reg = data.registration;\n      lastGeneratedWhatsAppText = data.whatsappText;\n\n      document.getElementById('ticketPassId').textContent = `#${reg.id}`;\n      document.getElementById('ticketName').textContent = reg.name;\n      document.getElementById('ticketBranch').textContent = reg.branch;\n      document.getElementById('ticketYear').textContent = reg.year;\n      document.getElementById('ticketPhone').textContent = reg.phone;\n\n      const waUrl = data.adminWhatsAppUrl || `https://wa.me/${ADMIN_PHONE}?text=${encodeURIComponent(lastGeneratedWhatsAppText)}`;\n      document.getElementById('openWhatsAppBtn').href = waUrl;\n\n      formView.style.display = 'none';\n      passSuccessView.style.display = 'block';\n\n      // Auto launch WhatsApp\n      try {\n        window.open(waUrl, '_blank');\n      } catch (e) {}\n    }\n\n    // Copy Pass Details button\n    document.getElementById('copyPassTextBtn').addEventListener('click', () => {\n      if (lastGeneratedWhatsAppText && navigator.clipboard) {\n        navigator.clipboard.writeText(lastGeneratedWhatsAppText).then(() => {\n          const btn = document.getElementById('copyPassTextBtn');\n          btn.innerHTML = '<span>✅ Pass Details Copied!</span>';\n          setTimeout(() => {\n            btn.innerHTML = '<span>📋 Copy Pass Information to Clipboard</span>';\n          }, 2500);\n        });\n      }\n    });\n\n    // Back to top button\n    document.getElementById('backToTopBtn').addEventListener('click', () => {\n      window.scrollTo({ top: 0, behavior: 'smooth' });\n    });\n  \n    // === AWWWARDS & GODLY INTERACTIVE SCRIPTS ===\n\n    // Toast Notification Helper\n    function showToast(msg) {\n      const toast = document.getElementById('toastNotification');\n      const text = document.getElementById('toastMessage');\n      if (toast && text) {\n        text.textContent = msg;\n        toast.classList.add('show');\n        setTimeout(() => toast.classList.remove('show'), 3000);\n      }\n    }\n\n    // Dynamic Card Spotlight (Godly / Awwwards)\n    document.querySelectorAll('.why__card, .sponsors__card, .testimonials__card, .venue__card').forEach(card => {\n      card.classList.add('card-spotlight');\n      card.addEventListener('mousemove', e => {\n        const rect = card.getBoundingClientRect();\n        const x = e.clientX - rect.left;\n        const y = e.clientY - rect.top;\n        card.style.setProperty('--mouse-x', `${x}px`);\n        card.style.setProperty('--mouse-y', `${y}px`);\n      });\n    });\n\n    // 3D Tilt Effect on Inventor Cards and Pass\n    document.querySelectorAll('.tilt-card').forEach(card => {\n      card.addEventListener('mousemove', e => {\n        const rect = card.getBoundingClientRect();\n        const x = e.clientX - rect.left;\n        const y = e.clientY - rect.top;\n        const centerX = rect.width / 2;\n        const centerY = rect.height / 2;\n        const rotateX = ((y - centerY) / centerY) * -7;\n        const rotateY = ((x - centerX) / centerX) * 7;\n        card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale3d(1.02, 1.02, 1.02)`;\n      });\n      card.addEventListener('mouseleave', () => {\n        card.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)';\n      });\n    });\n\n    // Schedule Track Filter Logic (Mobbin & Collect UI)\n    const filterButtons = document.querySelectorAll('.schedule-filter-btn');\n    const timelineItems = document.querySelectorAll('.timeline__item');\n    \n    // Assign tracks to timeline items\n    const trackAssignments = ['social', 'keynote', 'workshop', 'social', 'social', 'workshop', 'social', 'keynote'];\n    timelineItems.forEach((item, idx) => {\n      item.setAttribute('data-track', trackAssignments[idx] || 'all');\n    });\n\n    filterButtons.forEach(btn => {\n      btn.addEventListener('click', () => {\n        filterButtons.forEach(b => b.classList.remove('active'));\n        btn.classList.add('active');\n        const filter = btn.getAttribute('data-filter');\n\n        timelineItems.forEach(item => {\n          const track = item.getAttribute('data-track');\n          if (filter === 'all' || track === filter) {\n            item.style.display = 'flex';\n            item.style.opacity = '1';\n            item.style.transform = 'translateY(0)';\n          } else {\n            item.style.display = 'none';\n          }\n        });\n      });\n    });\n\n    // Print Ticket Handler\n    const printBtn = document.getElementById('printTicketBtn');\n    if (printBtn) {\n      printBtn.addEventListener('click', () => {\n        window.print();\n      });\n    }\n\n    // Enhance Copy Pass Action with Toast\n    const copyBtn = document.getElementById('copyPassTextBtn');\n    if (copyBtn) {\n      copyBtn.addEventListener('click', () => {\n        const passId = document.getElementById('ticketPassId').textContent;\n        showToast(`${passId} copied to clipboard!`);\n      });\n    }\n\n    // Number Count-Up Animation (Intersection Observer)\n    const observer = new IntersectionObserver((entries) => {\n      entries.forEach(entry => {\n        if (entry.isIntersecting) {\n          const target = entry.target;\n          if (target.dataset.counted) return;\n          target.dataset.counted = \"true\";\n\n          const text = target.textContent.trim();\n          const match = text.match(/^(\\d+)(\\+?)$/);\n          if (match) {\n            const finalNum = parseInt(match[1], 10);\n            const suffix = match[2] || '';\n            let current = 0;\n            const duration = 1200;\n            const stepTime = 25;\n            const steps = duration / stepTime;\n            const increment = Math.ceil(finalNum / steps);\n\n            const timer = setInterval(() => {\n              current += increment;\n              if (current >= finalNum) {\n                target.textContent = finalNum + suffix;\n                clearInterval(timer);\n              } else {\n                target.textContent = current + suffix;\n              }\n            }, stepTime);\n          }\n        }\n      });\n    }, { threshold: 0.5 });\n\n    document.querySelectorAll('.hero-stats__value, .venue__stat-num').forEach(el => {\n      observer.observe(el);\n    });\n\n  \n    // === WEB AUDIO API MICRO-HAPTIC FEEDBACK ===\n    function playHapticTick() {\n      try {\n        const AudioCtx = window.AudioContext || window.webkitAudioContext;\n        if (!AudioCtx) return;\n        const ctx = new AudioCtx();\n        const osc = ctx.createOscillator();\n        const gain = ctx.createGain();\n        osc.type = 'sine';\n        osc.frequency.setValueAtTime(850, ctx.currentTime);\n        osc.frequency.exponentialRampToValueAtTime(120, ctx.currentTime + 0.04);\n        gain.gain.setValueAtTime(0.045, ctx.currentTime);\n        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.04);\n        osc.connect(gain);\n        gain.connect(ctx.destination);\n        osc.start();\n        osc.stop(ctx.currentTime + 0.04);\n      } catch(e) {}\n    }\n\n    document.addEventListener('click', (e) => {\n      const target = e.target.closest('button, a, .btn, .schedule-filter-btn, .faq__trigger');\n      if (target) {\n        playHapticTick();\n      }\n    });\n\n    // === MAGNETIC BUTTONS WITH SPRING PHYSICS ===\n    document.querySelectorAll('.btn, #heroRegBtn, #navRegBtn, #ctaRegBtn, .mobile-floating-btn').forEach(btn => {\n      btn.addEventListener('mousemove', (e) => {\n        const rect = btn.getBoundingClientRect();\n        const x = e.clientX - rect.left - rect.width / 2;\n        const y = e.clientY - rect.top - rect.height / 2;\n        btn.style.transform = `translate(${x * 0.25}px, ${y * 0.25}px) scale(1.03)`;\n      });\n      btn.addEventListener('mouseleave', () => {\n        btn.style.transform = 'translate(0px, 0px) scale(1)';\n      });\n    });\n\n  </script>\n\n  <!-- MOBILE FLOATING CONVERSION BAR (ONE PAGE LOVE / LAND-BOOK) -->\n  <div class=\"mobile-floating-bar\" id=\"mobileFloatingBar\">\n    <div class=\"mobile-floating-info\">\n      <span class=\"mobile-floating-date\">📅 22 Aug 2026</span>\n      <span class=\"mobile-floating-seats\">● 100% Free Entry</span>\n    </div>\n    <button type=\"button\" class=\"mobile-floating-btn\" onclick=\"document.getElementById('navRegBtn').click()\">\n      Claim Free Pass ➔\n    </button>\n  </div>\n\n  <!-- FLOATING TOAST NOTIFICATION -->\n  <div id=\"toastNotification\" class=\"toast-notification\" role=\"status\" aria-live=\"polite\">\n    <span class=\"toast-icon\">✨</span>\n    <span id=\"toastMessage\">Pass Information Copied!</span>\n  </div>\n\n</body>\n</html>\n","adminHtml":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Admin Dashboard — AWS Community Day @ Rungta University</title>\n  \n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\n  \n  <!-- SheetJS for local browser Excel export if needed -->\n  <script src=\"https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js\"></script>\n\n  <style>\n    :root {\n      --bg-dark: #030712;\n      --card-bg: rgba(15, 23, 42, 0.75);\n      --card-border: rgba(56, 189, 248, 0.2);\n      --card-border-glow: rgba(56, 189, 248, 0.6);\n      --aws-orange: #ff9900;\n      --aws-blue: #38bdf8;\n      --emerald: #10b981;\n      --rose: #f43f5e;\n      --text-main: #ffffff;\n      --text-muted: #94a3b8;\n      --input-bg: #0f172a;\n    }\n\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      font-family: 'Plus Jakarta Sans', system-ui, sans-serif;\n    }\n\n    body {\n      background-color: var(--bg-dark);\n      color: var(--text-main);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n    }\n\n    /* Ambient Blueprint Grid */\n    .bg-grid {\n      position: fixed;\n      inset: 0;\n      background-image: \n        linear-gradient(to right, rgba(255, 255, 255, 0.03) 1px, transparent 1px),\n        linear-gradient(to bottom, rgba(255, 255, 255, 0.03) 1px, transparent 1px);\n      background-size: 36px 36px;\n      z-index: -1;\n      pointer-events: none;\n    }\n\n    .glow-aura {\n      position: fixed;\n      top: -15%;\n      right: 15%;\n      width: 500px;\n      height: 500px;\n      background: radial-gradient(circle, rgba(56, 189, 248, 0.12) 0%, rgba(3, 105, 161, 0.04) 50%, transparent 70%);\n      filter: blur(80px);\n      z-index: -1;\n      pointer-events: none;\n    }\n\n    /* Header */\n    header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 1.1rem 2rem;\n      background: rgba(3, 7, 18, 0.9);\n      border-bottom: 1px solid var(--card-border);\n      position: sticky;\n      top: 0;\n      z-index: 100;\n      backdrop-filter: blur(16px);\n      flex-wrap: wrap;\n      gap: 1rem;\n    }\n\n    .header-left {\n      display: flex;\n      align-items: center;\n      gap: 1rem;\n    }\n\n    .logo-badge {\n      background: linear-gradient(135deg, var(--aws-orange), #ff5500);\n      color: #000;\n      font-size: 0.72rem;\n      font-weight: 900;\n      padding: 0.25rem 0.6rem;\n      border-radius: 6px;\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n    }\n\n    .logo-text {\n      font-weight: 800;\n      font-size: 1.15rem;\n    }\n\n    .logo-text span {\n      color: var(--aws-blue);\n    }\n\n    .admin-pill {\n      background: rgba(56, 189, 248, 0.12);\n      border: 1px solid var(--card-border-glow);\n      color: var(--aws-blue);\n      font-size: 0.75rem;\n      font-weight: 700;\n      padding: 0.2rem 0.6rem;\n      border-radius: 99px;\n      font-family: 'JetBrains Mono', monospace;\n      display: inline-flex;\n      align-items: center;\n      gap: 0.4rem;\n    }\n\n    .header-actions {\n      display: flex;\n      align-items: center;\n      gap: 0.75rem;\n      flex-wrap: wrap;\n    }\n\n    /* Buttons */\n    .btn {\n      padding: 0.6rem 1.1rem;\n      border-radius: 8px;\n      font-size: 0.85rem;\n      font-weight: 700;\n      cursor: pointer;\n      display: inline-flex;\n      align-items: center;\n      gap: 0.5rem;\n      text-decoration: none;\n      transition: all 0.2s ease;\n      border: 1px solid transparent;\n      outline: none;\n    }\n\n    .btn-outline {\n      background: rgba(15, 23, 42, 0.8);\n      border-color: var(--card-border);\n      color: var(--text-main);\n    }\n\n    .btn-outline:hover {\n      border-color: var(--card-border-glow);\n      background: rgba(30, 41, 59, 0.9);\n    }\n\n    .btn-excel {\n      background: linear-gradient(135deg, #107c41, #15803d);\n      color: #ffffff;\n      border-color: rgba(34, 197, 94, 0.4);\n      box-shadow: 0 0 15px rgba(22, 163, 74, 0.3);\n    }\n\n    .btn-excel:hover {\n      background: #16a34a;\n      transform: translateY(-1px);\n      box-shadow: 0 0 20px rgba(22, 163, 74, 0.5);\n    }\n\n    .btn-whatsapp {\n      background: linear-gradient(135deg, #25d366, #128c7e);\n      color: #ffffff;\n    }\n\n    .btn-whatsapp:hover {\n      background: #25d366;\n      box-shadow: 0 0 18px rgba(37, 211, 102, 0.4);\n    }\n\n    .btn-primary {\n      background: linear-gradient(135deg, #0284c7, #0369a1);\n      color: #ffffff;\n    }\n\n    .btn-primary:hover {\n      background: #0284c7;\n    }\n\n    /* Main Container */\n    .container {\n      max-width: 1300px;\n      width: 100%;\n      margin: 0 auto;\n      padding: 2rem 1.5rem 3rem;\n      flex: 1;\n    }\n\n    /* Stats Grid */\n    .stats-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n      gap: 1.2rem;\n      margin-bottom: 2rem;\n    }\n\n    .stat-card {\n      background: var(--card-bg);\n      border: 1px solid var(--card-border);\n      border-radius: 14px;\n      padding: 1.4rem;\n      position: relative;\n      overflow: hidden;\n      transition: border-color 0.2s;\n    }\n\n    .stat-card:hover {\n      border-color: var(--card-border-glow);\n    }\n\n    .stat-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 0.8rem;\n    }\n\n    .stat-title {\n      color: var(--text-muted);\n      font-size: 0.82rem;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n    }\n\n    .stat-icon {\n      font-size: 1.3rem;\n    }\n\n    .stat-value {\n      font-size: 2.2rem;\n      font-weight: 900;\n      font-family: 'JetBrains Mono', monospace;\n      color: #ffffff;\n      line-height: 1;\n      margin-bottom: 0.4rem;\n    }\n\n    .stat-subtext {\n      color: var(--text-muted);\n      font-size: 0.8rem;\n    }\n\n    .stat-subtext strong {\n      color: var(--aws-blue);\n    }\n\n    /* Table Toolbar */\n    .toolbar-panel {\n      background: var(--card-bg);\n      border: 1px solid var(--card-border);\n      border-radius: 14px 14px 0 0;\n      padding: 1.2rem 1.4rem;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      flex-wrap: wrap;\n      gap: 1rem;\n    }\n\n    .toolbar-title {\n      font-size: 1.15rem;\n      font-weight: 800;\n      display: flex;\n      align-items: center;\n      gap: 0.6rem;\n    }\n\n    .toolbar-filters {\n      display: flex;\n      align-items: center;\n      gap: 0.8rem;\n      flex-wrap: wrap;\n      flex: 1;\n      justify-content: flex-end;\n    }\n\n    .search-box {\n      position: relative;\n      min-width: 240px;\n      max-width: 320px;\n      flex: 1;\n    }\n\n    .search-box input {\n      width: 100%;\n      padding: 0.55rem 0.9rem 0.55rem 2.2rem;\n      background: var(--input-bg);\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      color: #fff;\n      font-size: 0.85rem;\n      outline: none;\n      transition: border-color 0.2s;\n    }\n\n    .search-box input:focus {\n      border-color: var(--aws-blue);\n    }\n\n    .search-box span {\n      position: absolute;\n      left: 0.75rem;\n      top: 50%;\n      transform: translateY(-50%);\n      color: var(--text-muted);\n      font-size: 0.85rem;\n    }\n\n    .filter-select {\n      background: var(--input-bg);\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      color: #fff;\n      padding: 0.55rem 0.85rem;\n      font-size: 0.85rem;\n      outline: none;\n      cursor: pointer;\n    }\n\n    .filter-select:focus {\n      border-color: var(--aws-blue);\n    }\n\n    /* Table Container */\n    .table-container {\n      background: var(--card-bg);\n      border: 1px solid var(--card-border);\n      border-top: none;\n      border-radius: 0 0 14px 14px;\n      overflow-x: auto;\n    }\n\n    table {\n      width: 100%;\n      border-collapse: collapse;\n      text-align: left;\n      font-size: 0.88rem;\n    }\n\n    thead {\n      background: rgba(3, 7, 18, 0.7);\n      border-bottom: 1px solid var(--card-border);\n    }\n\n    th {\n      padding: 0.9rem 1.2rem;\n      color: var(--text-muted);\n      font-weight: 700;\n      font-size: 0.78rem;\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n      white-space: nowrap;\n    }\n\n    tbody tr {\n      border-bottom: 1px solid rgba(255, 255, 255, 0.05);\n      transition: background 0.15s ease;\n    }\n\n    tbody tr:hover {\n      background: rgba(56, 189, 248, 0.04);\n    }\n\n    td {\n      padding: 0.9rem 1.2rem;\n      vertical-align: middle;\n      white-space: nowrap;\n    }\n\n    .pass-tag {\n      background: rgba(56, 189, 248, 0.12);\n      border: 1px solid rgba(56, 189, 248, 0.3);\n      color: var(--aws-blue);\n      font-family: 'JetBrains Mono', monospace;\n      font-weight: 700;\n      font-size: 0.8rem;\n      padding: 0.25rem 0.55rem;\n      border-radius: 6px;\n      display: inline-flex;\n      align-items: center;\n      gap: 0.3rem;\n    }\n\n    .student-name {\n      font-weight: 700;\n      color: #ffffff;\n    }\n\n    .student-meta {\n      color: var(--text-muted);\n      font-size: 0.78rem;\n      margin-top: 0.15rem;\n    }\n\n    .badge-branch {\n      display: inline-block;\n      padding: 0.2rem 0.55rem;\n      border-radius: 6px;\n      font-size: 0.75rem;\n      font-weight: 700;\n      background: rgba(255, 153, 0, 0.15);\n      border: 1px solid rgba(255, 153, 0, 0.4);\n      color: var(--aws-orange);\n    }\n\n    .badge-year {\n      display: inline-block;\n      padding: 0.2rem 0.55rem;\n      border-radius: 6px;\n      font-size: 0.75rem;\n      font-weight: 700;\n      background: rgba(99, 102, 241, 0.15);\n      border: 1px solid rgba(99, 102, 241, 0.4);\n      color: #a5b4fc;\n    }\n\n    .action-btn {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      width: 32px;\n      height: 32px;\n      border-radius: 6px;\n      border: 1px solid var(--card-border);\n      background: var(--input-bg);\n      color: var(--text-main);\n      cursor: pointer;\n      font-size: 0.95rem;\n      transition: all 0.2s;\n      text-decoration: none;\n    }\n\n    .action-btn.whatsapp:hover {\n      background: #25d366;\n      border-color: #25d366;\n      color: #fff;\n    }\n\n    .action-btn.delete:hover {\n      background: var(--rose);\n      border-color: var(--rose);\n      color: #fff;\n    }\n\n    /* Empty state */\n    .empty-state {\n      text-align: center;\n      padding: 4rem 1.5rem;\n      color: var(--text-muted);\n    }\n\n    .empty-state-icon {\n      font-size: 3rem;\n      margin-bottom: 1rem;\n      opacity: 0.7;\n    }\n\n    /* Modals */\n    .modal-overlay {\n      display: none;\n      position: fixed;\n      inset: 0;\n      background: rgba(3, 7, 18, 0.85);\n      z-index: 1000;\n      justify-content: center;\n      align-items: center;\n      padding: 1.2rem;\n      backdrop-filter: blur(8px);\n    }\n\n    .modal-overlay.active {\n      display: flex !important;\n    }\n\n    .modal-card {\n      background: #0f172a;\n      border: 1px solid var(--card-border-glow);\n      border-radius: 14px;\n      padding: 2rem;\n      width: 100%;\n      max-width: 480px;\n      position: relative;\n      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.8);\n    }\n\n    .modal-card h2 {\n      font-size: 1.25rem;\n      font-weight: 800;\n      margin-bottom: 0.5rem;\n      color: #fff;\n    }\n\n    .modal-card p.sub {\n      color: var(--text-muted);\n      font-size: 0.85rem;\n      margin-bottom: 1.4rem;\n      line-height: 1.4;\n    }\n\n    .form-group {\n      margin-bottom: 1.2rem;\n    }\n\n    .form-group label {\n      display: block;\n      margin-bottom: 0.4rem;\n      font-size: 0.82rem;\n      font-weight: 700;\n      color: var(--text-muted);\n    }\n\n    .form-group input {\n      width: 100%;\n      padding: 0.75rem 0.9rem;\n      background: #030712;\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      color: #fff;\n      font-size: 0.9rem;\n      outline: none;\n    }\n\n    .form-group input:focus {\n      border-color: var(--aws-blue);\n    }\n\n    .modal-actions {\n      display: flex;\n      justify-content: flex-end;\n      gap: 0.75rem;\n      margin-top: 1.5rem;\n    }\n\n    .close-btn {\n      position: absolute;\n      top: 1rem;\n      right: 1.2rem;\n      background: transparent;\n      border: none;\n      color: var(--text-muted);\n      font-size: 1.5rem;\n      cursor: pointer;\n    }\n\n    .close-btn:hover {\n      color: #fff;\n    }\n\n    /* Toast Notification */\n    .toast {\n      position: fixed;\n      bottom: 24px;\n      right: 24px;\n      background: rgba(15, 23, 42, 0.95);\n      border: 1px solid var(--card-border-glow);\n      color: #ffffff;\n      padding: 0.9rem 1.4rem;\n      border-radius: 10px;\n      font-size: 0.88rem;\n      font-weight: 600;\n      display: flex;\n      align-items: center;\n      gap: 0.6rem;\n      box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);\n      z-index: 2000;\n      transform: translateY(100px);\n      opacity: 0;\n      transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n\n    .toast.show {\n      transform: translateY(0);\n      opacity: 1;\n    }\n\n    /* LOGIN SCREEN STYLING */\n    .login-wrapper {\n      min-height: 100vh;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      padding: 1.5rem;\n      position: relative;\n      z-index: 10;\n    }\n\n    .login-box {\n      background: rgba(15, 23, 42, 0.9);\n      border: 1px solid var(--card-border-glow);\n      border-radius: 16px;\n      padding: 2.4rem 2rem;\n      width: 100%;\n      max-width: 420px;\n      box-shadow: 0 25px 60px rgba(0, 0, 0, 0.85);\n      backdrop-filter: blur(16px);\n      text-align: center;\n      animation: modalFadeIn 0.3s ease;\n    }\n\n    .login-header-logo {\n      display: inline-flex;\n      align-items: center;\n      gap: 0.6rem;\n      margin-bottom: 1.2rem;\n    }\n\n    .login-box h2 {\n      font-size: 1.35rem;\n      font-weight: 800;\n      color: #ffffff;\n      margin-bottom: 0.4rem;\n    }\n\n    .login-box p.login-sub {\n      color: var(--text-muted);\n      font-size: 0.84rem;\n      margin-bottom: 1.6rem;\n    }\n\n    .login-form-group {\n      text-align: left;\n      margin-bottom: 1.2rem;\n    }\n\n    .login-form-group label {\n      display: block;\n      font-size: 0.8rem;\n      font-weight: 700;\n      color: var(--text-muted);\n      margin-bottom: 0.4rem;\n      font-family: 'JetBrains Mono', monospace;\n    }\n\n    .login-form-group input {\n      width: 100%;\n      padding: 0.8rem 0.95rem;\n      background: #030712;\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      color: #fff;\n      font-size: 0.92rem;\n      outline: none;\n      transition: border-color 0.2s;\n    }\n\n    .login-form-group input:focus {\n      border-color: var(--aws-blue);\n      box-shadow: 0 0 15px rgba(56, 189, 248, 0.2);\n    }\n\n    .btn-login-submit {\n      width: 100%;\n      background: linear-gradient(135deg, #0284c7 0%, #0369a1 50%, #6366f1 100%);\n      color: #fff;\n      border: none;\n      padding: 0.85rem;\n      font-size: 0.92rem;\n      font-weight: 800;\n      border-radius: 8px;\n      cursor: pointer;\n      margin-top: 0.5rem;\n      transition: all 0.2s ease;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 0.5rem;\n    }\n\n    .btn-login-submit:hover {\n      box-shadow: 0 0 25px rgba(56, 189, 248, 0.6);\n      transform: translateY(-1px);\n    }\n\n    .login-alert {\n      display: none;\n      background: rgba(244, 63, 94, 0.15);\n      border: 1px solid rgba(244, 63, 94, 0.4);\n      color: #fda4af;\n      padding: 0.6rem 0.8rem;\n      border-radius: 8px;\n      font-size: 0.82rem;\n      margin-bottom: 1.2rem;\n      text-align: left;\n    }\n\n    .default-creds-hint {\n      margin-top: 1.5rem;\n      background: rgba(56, 189, 248, 0.08);\n      border: 1px dashed rgba(56, 189, 248, 0.3);\n      padding: 0.8rem;\n      border-radius: 8px;\n      font-size: 0.78rem;\n      color: var(--text-muted);\n      line-height: 1.5;\n    }\n\n    .default-creds-hint code {\n      color: var(--aws-blue);\n      font-weight: 700;\n      font-family: 'JetBrains Mono', monospace;\n    }\n\n    footer {\n      text-align: center;\n      padding: 1.5rem;\n      color: var(--text-muted);\n      font-size: 0.8rem;\n      border-top: 1px solid var(--card-border);\n    }\n  </style>\n</head>\n<body>\n\n  <div class=\"bg-grid\"></div>\n  <div class=\"glow-aura\"></div>\n\n  <!-- LOGIN VIEW -->\n  <div id=\"loginView\" class=\"login-wrapper\">\n    <div class=\"login-box\">\n      <div class=\"login-header-logo\">\n        <span class=\"logo-badge\">AWS</span>\n        <div class=\"logo-text\">Student <span>Builder</span></div>\n      </div>\n      \n      <h2>🔐 Admin Security Gateway</h2>\n      <p class=\"login-sub\">Enter your authorized credentials to access the registration database & tools.</p>\n\n      <div class=\"login-alert\" id=\"loginAlert\">\n        ⚠️ Invalid username or password. Please try again.\n      </div>\n\n      <form id=\"adminLoginForm\">\n        <div class=\"login-form-group\">\n          <label for=\"loginUsername\">ADMIN USERNAME</label>\n          <input type=\"text\" id=\"loginUsername\" placeholder=\"e.g. admin\" required autocomplete=\"username\" autofocus>\n        </div>\n\n        <div class=\"login-form-group\">\n          <label for=\"loginPassword\">PASSWORD</label>\n          <input type=\"password\" id=\"loginPassword\" placeholder=\"••••••••\" required autocomplete=\"current-password\">\n        </div>\n\n        <button type=\"submit\" class=\"btn-login-submit\" id=\"loginSubmitBtn\">\n          ⚡ SIGN IN TO DASHBOARD &rarr;\n        </button>\n      </form>\n\n      <div style=\"margin-top: 1.5rem;\">\n        <a href=\"index.html\" style=\"color: var(--aws-blue); text-decoration: none; font-size: 0.85rem; font-weight: 700;\">\n          &larr; Back to Registration Website\n        </a>\n      </div>\n    </div>\n  </div>\n\n  <!-- DASHBOARD VIEW -->\n  <div id=\"dashboardView\" style=\"display: none; min-height: 100vh; flex-direction: column;\">\n    <!-- Header -->\n    <header>\n      <div class=\"header-left\">\n        <span class=\"logo-badge\">AWS</span>\n        <div class=\"logo-text\">Student <span>Builder</span></div>\n        <span class=\"admin-pill\">⚡ ADMIN CONSOLE</span>\n      </div>\n\n      <div class=\"header-actions\">\n        <a href=\"index.html\" class=\"btn btn-outline\" target=\"_blank\" title=\"Open student registration website\">\n          🌐 View Live Site ↗\n        </a>\n        \n        <button class=\"btn btn-outline\" id=\"openSettingsBtn\" title=\"Set Admin WhatsApp Number\">\n          ⚙️ WhatsApp Settings\n        </button>\n\n        <a href=\"https://script.google.com/macros/s/AKfycbz2nqsYrezuQ-FTOGoQQbDKpdEZW8ZPSLGx5YZzUhe29650r0Jb9ABoNWRVndstq-JJ/exec\" target=\"_blank\" class=\"btn btn-outline\" style=\"border-color: rgba(16, 185, 129, 0.4); color: #34d399;\" title=\"Google Sheet Webhook (Live JSON & Sync)\">\n          🟢 Google Sheet Live ↗\n        </a>\n\n        <!-- EXCEL EXPORT BUTTON -->\n        <button class=\"btn btn-excel\" id=\"exportExcelBtn\" title=\"Export registrations directly to formatted Excel\">\n          📊 Export to Excel (.xlsx)\n        </button>\n\n        <button class=\"btn btn-outline\" id=\"exportCsvBtn\" title=\"Download CSV format\">\n          📄 Export CSV\n        </button>\n\n        <!-- LOGOUT BUTTON -->\n        <button class=\"btn btn-outline\" id=\"logoutBtn\" style=\"border-color: rgba(244, 63, 94, 0.4); color: #fda4af;\" title=\"Log out from Admin Console\">\n          🚪 Logout\n        </button>\n      </div>\n    </header>\n\n  <!-- Main Content -->\n  <div class=\"container\">\n    <!-- Statistics Cards -->\n    <div class=\"stats-grid\">\n      <div class=\"stat-card\">\n        <div class=\"stat-header\">\n          <span class=\"stat-title\">Total Registrations</span>\n          <span class=\"stat-icon\">👥</span>\n        </div>\n        <div class=\"stat-value\" id=\"statTotal\">0</div>\n        <div class=\"stat-subtext\">Confirmed student passes issued</div>\n      </div>\n\n      <div class=\"stat-card\">\n        <div class=\"stat-header\">\n          <span class=\"stat-title\">Registered Today</span>\n          <span class=\"stat-icon\">⚡</span>\n        </div>\n        <div class=\"stat-value\" id=\"statToday\">0</div>\n        <div class=\"stat-subtext\">New signups recorded today</div>\n      </div>\n\n      <div class=\"stat-card\">\n        <div class=\"stat-header\">\n          <span class=\"stat-title\">Top Branch</span>\n          <span class=\"stat-icon\">🎓</span>\n        </div>\n        <div class=\"stat-value\" id=\"statTopBranch\" style=\"font-size: 1.5rem; padding-top: 0.4rem;\">None</div>\n        <div class=\"stat-subtext\" id=\"statTopBranchSub\">No branch data yet</div>\n      </div>\n\n      <div class=\"stat-card\">\n        <div class=\"stat-header\">\n          <span class=\"stat-title\">Admin WhatsApp</span>\n          <span class=\"stat-icon\">📱</span>\n        </div>\n        <div class=\"stat-value\" id=\"statWhatsApp\" style=\"font-size: 1.25rem; padding-top: 0.5rem; color: #25d366;\">\n          Not Set\n        </div>\n        <div class=\"stat-subtext\">Click 'WhatsApp Settings' to configure</div>\n      </div>\n    </div>\n\n    <!-- Table Toolbar -->\n    <div class=\"toolbar-panel\">\n      <div class=\"toolbar-title\">\n        <span>Registered Students</span>\n        <span class=\"pass-tag\" id=\"tableCountTag\">0 records</span>\n      </div>\n\n      <div class=\"toolbar-filters\">\n        <div class=\"search-box\">\n          <span>🔍</span>\n          <input type=\"text\" id=\"searchInput\" placeholder=\"Search by name, phone, email, pass ID...\">\n        </div>\n\n        <select id=\"branchFilter\" class=\"filter-select\">\n          <option value=\"\">All Branches</option>\n          <option value=\"CSE\">CSE</option>\n          <option value=\"IT\">IT</option>\n          <option value=\"AI_DS\">AI & Data Science</option>\n          <option value=\"ECE\">ECE</option>\n          <option value=\"EEE\">EEE</option>\n          <option value=\"MECH\">Mechanical</option>\n          <option value=\"CIVIL\">Civil</option>\n          <option value=\"OTHER\">Other</option>\n        </select>\n\n        <select id=\"yearFilter\" class=\"filter-select\">\n          <option value=\"\">All Years</option>\n          <option value=\"1\">1st Year</option>\n          <option value=\"2\">2nd Year</option>\n          <option value=\"3\">3rd Year</option>\n          <option value=\"4\">4th Year</option>\n        </select>\n\n        <button class=\"btn btn-outline\" id=\"refreshBtn\" title=\"Refresh data\">\n          🔄 Refresh\n        </button>\n      </div>\n    </div>\n\n    <!-- Table Container -->\n    <div class=\"table-container\">\n      <table>\n        <thead>\n          <tr>\n            <th>Pass ID</th>\n            <th>Student Name</th>\n            <th>Contact Details</th>\n            <th>Branch</th>\n            <th>Year & Sec</th>\n            <th>Date & Time</th>\n            <th style=\"text-align: right;\">Actions</th>\n          </tr>\n        </thead>\n        <tbody id=\"registrationsTableBody\">\n          <!-- Populated by JavaScript -->\n        </tbody>\n      </table>\n\n      <div class=\"empty-state\" id=\"emptyState\" style=\"display: none;\">\n        <div class=\"empty-state-icon\">📋</div>\n        <h3 style=\"color: #fff; margin-bottom: 0.4rem;\">No registrations found</h3>\n        <p>No students have registered yet or no records match your filter.</p>\n      </div>\n    </div>\n  </div>\n\n  <!-- WhatsApp Settings Modal -->\n  <div class=\"modal-overlay\" id=\"settingsModal\">\n    <div class=\"modal-card\">\n      <button class=\"close-btn\" id=\"closeSettingsModal\">&times;</button>\n      <h2>⚙️ WhatsApp & Event Settings</h2>\n      <p class=\"sub\">Configure the WhatsApp phone number where you want to receive registration details and inquiries.</p>\n\n      <form id=\"settingsForm\">\n        <div class=\"form-group\">\n          <label for=\"adminWhatsAppInput\">Admin WhatsApp Number (with Country Code):</label>\n          <input type=\"tel\" id=\"adminWhatsAppInput\" placeholder=\"e.g. 919876543210\" required>\n          <span style=\"font-size: 0.76rem; color: var(--text-muted); display: block; margin-top: 0.35rem;\">\n            Include 91 for India (e.g. 919826012345). No + or spaces needed.\n          </span>\n        </div>\n\n        <div class=\"modal-actions\">\n          <button type=\"button\" class=\"btn btn-outline\" id=\"cancelSettingsBtn\">Cancel</button>\n          <button type=\"submit\" class=\"btn btn-whatsapp\">Save WhatsApp Number</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- Toast -->\n  <div class=\"toast\" id=\"toast\">\n    <span id=\"toastIcon\">✅</span>\n    <span id=\"toastMsg\">Operation successful</span>\n  </div>\n\n  <footer>\n    &copy; AWS Student Builder Group — Admin Control Room &bull; Rungta University\n  </footer>\n  </div><!-- /dashboardView -->\n\n  <script>\n    // State\n    let allRegistrations = [];\n    let settings = { adminWhatsApp: '919343756202' };\n\n    // Auth & View References\n    const loginView = document.getElementById('loginView');\n    const dashboardView = document.getElementById('dashboardView');\n    const adminLoginForm = document.getElementById('adminLoginForm');\n    const loginUsername = document.getElementById('loginUsername');\n    const loginPassword = document.getElementById('loginPassword');\n    const loginAlert = document.getElementById('loginAlert');\n    const loginSubmitBtn = document.getElementById('loginSubmitBtn');\n    const logoutBtn = document.getElementById('logoutBtn');\n\n    // DOM References\n    const tableBody = document.getElementById('registrationsTableBody');\n    const emptyState = document.getElementById('emptyState');\n    const searchInput = document.getElementById('searchInput');\n    const branchFilter = document.getElementById('branchFilter');\n    const yearFilter = document.getElementById('yearFilter');\n    const tableCountTag = document.getElementById('tableCountTag');\n    const statTotal = document.getElementById('statTotal');\n    const statToday = document.getElementById('statToday');\n    const statTopBranch = document.getElementById('statTopBranch');\n    const statTopBranchSub = document.getElementById('statTopBranchSub');\n    const statWhatsApp = document.getElementById('statWhatsApp');\n    const settingsModal = document.getElementById('settingsModal');\n    const settingsForm = document.getElementById('settingsForm');\n    const adminWhatsAppInput = document.getElementById('adminWhatsAppInput');\n    const toast = document.getElementById('toast');\n    const toastMsg = document.getElementById('toastMsg');\n    const toastIcon = document.getElementById('toastIcon');\n\n    // Show Toast\n    function showToast(msg, icon = '✅') {\n      toastMsg.textContent = msg;\n      toastIcon.textContent = icon;\n      toast.classList.add('show');\n      setTimeout(() => toast.classList.remove('show'), 3500);\n    }\n\n    const GOOGLE_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbz2nqsYrezuQ-FTOGoQQbDKpdEZW8ZPSLGx5YZzUhe29650r0Jb9ABoNWRVndstq-JJ/exec';\n\n    // Fetch Registrations from server and Google Sheet (with localStorage fallback)\n    async function loadData() {\n      const localList = JSON.parse(localStorage.getItem('aws_registrations_cache') || '[]');\n      let serverList = [];\n      let sheetList = [];\n\n      // 1. Try local server API\n      try {\n        const res = await fetch('/api/registrations');\n        if (res.ok) {\n          const data = await res.json();\n          serverList = data.registrations || [];\n          if (data.settings) settings = data.settings;\n        }\n      } catch (err) {\n        console.warn('Local backend not reachable:', err);\n      }\n\n      // 2. Try Google Sheets Webhook directly\n      try {\n        const sheetRes = await fetch(GOOGLE_SCRIPT_URL);\n        if (sheetRes.ok) {\n          const sheetData = await sheetRes.json();\n          if (sheetData && Array.isArray(sheetData.registrations)) {\n            sheetList = sheetData.registrations;\n          }\n        }\n      } catch (sheetErr) {\n        console.warn('Google Sheet direct fetch warning:', sheetErr);\n      }\n\n      // Merge all sources by ID\n      const map = new Map();\n      [...serverList, ...sheetList, ...localList].forEach(item => {\n        if (item && item.id) map.set(item.id, item);\n      });\n      allRegistrations = Array.from(map.values());\n\n      if (!settings.adminWhatsApp) settings.adminWhatsApp = '919343756202';\n      localStorage.setItem('aws_registrations_cache', JSON.stringify(allRegistrations));\n      localStorage.setItem('aws_settings_cache', JSON.stringify(settings));\n\n      updateUI();\n    }\n\n    // Update Dashboard Metrics and Table\n    function updateUI() {\n      // 1. Stats\n      const total = allRegistrations.length;\n      statTotal.textContent = total;\n\n      const todayStr = new Date().toISOString().slice(0, 10);\n      const todayCount = allRegistrations.filter(r => r.registeredAt && r.registeredAt.startsWith(todayStr)).length;\n      statToday.textContent = todayCount;\n\n      // Top Branch\n      const branchCounts = {};\n      allRegistrations.forEach(r => {\n        branchCounts[r.branch] = (branchCounts[r.branch] || 0) + 1;\n      });\n      let topBranch = null;\n      let topCount = 0;\n      for (const [branch, count] of Object.entries(branchCounts)) {\n        if (count > topCount) {\n          topBranch = branch;\n          topCount = count;\n        }\n      }\n      if (topBranch) {\n        statTopBranch.textContent = topBranch;\n        statTopBranchSub.textContent = `${topCount} student${topCount > 1 ? 's' : ''} enrolled`;\n      } else {\n        statTopBranch.textContent = 'None';\n        statTopBranchSub.textContent = 'No branch data yet';\n      }\n\n      // WhatsApp status\n      if (settings.adminWhatsApp) {\n        statWhatsApp.textContent = '+' + settings.adminWhatsApp;\n      } else {\n        statWhatsApp.textContent = 'Not Configured';\n      }\n\n      // 2. Filter Table\n      renderTable();\n    }\n\n    function renderTable() {\n      const q = searchInput.value.toLowerCase().trim();\n      const bFilter = branchFilter.value;\n      const yFilter = yearFilter.value;\n\n      const filtered = allRegistrations.filter(item => {\n        const matchesQuery = !q ||\n          (item.name && item.name.toLowerCase().includes(q)) ||\n          (item.email && item.email.toLowerCase().includes(q)) ||\n          (item.phone && item.phone.includes(q)) ||\n          (item.id && item.id.toLowerCase().includes(q)) ||\n          (item.branch && item.branch.toLowerCase().includes(q)) ||\n          (item.section && item.section.toLowerCase().includes(q));\n\n        const matchesBranch = !bFilter || item.branch === bFilter;\n        const matchesYear = !yFilter || item.year === yFilter;\n\n        return matchesQuery && matchesBranch && matchesYear;\n      });\n\n      tableCountTag.textContent = `${filtered.length} of ${allRegistrations.length}`;\n\n      if (filtered.length === 0) {\n        tableBody.innerHTML = '';\n        emptyState.style.display = 'block';\n        return;\n      }\n\n      emptyState.style.display = 'none';\n      tableBody.innerHTML = filtered.map(item => {\n        const cleanPhone = item.phone.replace(/[^0-9]/g, '');\n        const phoneWithCountry = cleanPhone.length === 10 ? `91${cleanPhone}` : cleanPhone;\n        \n        const whatsappMsg = `Hi ${item.name}! This is from the AWS Student Builder Community Day team @ Rungta University. Your Entry Pass ID is #${item.id}. Let us know if you have any questions!`;\n        const waLink = `https://wa.me/${phoneWithCountry}?text=${encodeURIComponent(whatsappMsg)}`;\n\n        return `\n          <tr>\n            <td>\n              <span class=\"pass-tag\">🎟️ ${item.id}</span>\n            </td>\n            <td>\n              <div class=\"student-name\">${escapeHtml(item.name)}</div>\n            </td>\n            <td>\n              <div style=\"font-size: 0.85rem; color: #fff;\">${escapeHtml(item.phone)}</div>\n              <div class=\"student-meta\">${escapeHtml(item.email)}</div>\n            </td>\n            <td>\n              <span class=\"badge-branch\">${escapeHtml(item.branch)}</span>\n            </td>\n            <td>\n              <span class=\"badge-year\">${item.year} Yr &bull; Sec ${escapeHtml(item.section)}</span>\n            </td>\n            <td>\n              <div style=\"color: var(--text-muted); font-size: 0.82rem;\">${item.formattedDate || (item.registeredAt ? new Date(item.registeredAt).toLocaleDateString() : 'N/A')}</div>\n            </td>\n            <td style=\"text-align: right;\">\n              <div style=\"display: inline-flex; gap: 0.4rem;\">\n                <a href=\"${waLink}\" target=\"_blank\" class=\"action-btn whatsapp\" title=\"Chat with ${escapeHtml(item.name)} on WhatsApp\">\n                  💬\n                </a>\n                <button onclick=\"deleteRecord('${item.id}')\" class=\"action-btn delete\" title=\"Delete record\">\n                  🗑️\n                </button>\n              </div>\n            </td>\n          </tr>\n        `;\n      }).join('');\n    }\n\n    function escapeHtml(str) {\n      if (!str) return '';\n      return String(str).replace(/[&<>\"']/g, m => ({\n        '&': '&amp;',\n        '<': '&lt;',\n        '>': '&gt;',\n        '\"': '&quot;',\n        \"'\": '&#39;'\n      })[m]);\n    }\n\n    // Delete Record\n    async function deleteRecord(id) {\n      if (!confirm(`Are you sure you want to delete registration ${id}?`)) return;\n\n      try {\n        const res = await fetch(`/api/registrations/${id}`, { method: 'DELETE' });\n        if (res.ok) {\n          showToast(`Deleted ${id}`, '🗑️');\n        }\n      } catch (e) {\n        console.warn('Backend delete failed, removing locally:', e);\n      }\n\n      allRegistrations = allRegistrations.filter(r => r.id !== id);\n      localStorage.setItem('aws_registrations_cache', JSON.stringify(allRegistrations));\n      updateUI();\n    }\n\n    // EXCEL EXPORT\n    document.getElementById('exportExcelBtn').addEventListener('click', async function() {\n      if (allRegistrations.length === 0) {\n        alert('No registrations available to export.');\n        return;\n      }\n\n      // Try server-side export first for native server response\n      try {\n        const response = await fetch('/api/export-excel');\n        if (response.ok) {\n          const blob = await response.blob();\n          const url = window.URL.createObjectURL(blob);\n          const a = document.createElement('a');\n          a.href = url;\n          a.download = `AWS_Community_Day_Registrations_${new Date().toISOString().slice(0, 10)}.xlsx`;\n          document.body.appendChild(a);\n          a.click();\n          a.remove();\n          showToast('Excel (.xlsx) downloaded successfully! 📊');\n          return;\n        }\n      } catch (err) {\n        console.warn('Server Excel endpoint error, falling back to client-side SheetJS:', err);\n      }\n\n      // Client-side SheetJS fallback\n      if (typeof XLSX !== 'undefined') {\n        const exportData = allRegistrations.map((item, idx) => ({\n          'S.No': idx + 1,\n          'Pass ID': item.id,\n          'Full Name': item.name,\n          'Email': item.email,\n          'Mobile': item.phone,\n          'Branch': item.branch,\n          'Year': `${item.year} Year`,\n          'Section': item.section,\n          'Registered On': item.formattedDate || item.registeredAt\n        }));\n\n        const ws = XLSX.utils.json_to_sheet(exportData);\n        ws['!cols'] = [\n          { wch: 6 }, { wch: 15 }, { wch: 24 }, { wch: 30 },\n          { wch: 16 }, { wch: 14 }, { wch: 12 }, { wch: 10 }, { wch: 24 }\n        ];\n        const wb = XLSX.utils.book_new();\n        XLSX.utils.book_append_sheet(wb, ws, 'Registrations');\n        XLSX.writeFile(wb, `AWS_Community_Day_Registrations_${new Date().toISOString().slice(0, 10)}.xlsx`);\n        showToast('Excel (.xlsx) downloaded successfully! 📊');\n      } else {\n        alert('Could not export to Excel. Please check connection.');\n      }\n    });\n\n    // CSV EXPORT\n    document.getElementById('exportCsvBtn').addEventListener('click', function() {\n      if (allRegistrations.length === 0) {\n        alert('No registrations available to export.');\n        return;\n      }\n\n      const headers = ['S.No', 'Pass ID', 'Full Name', 'Email', 'Mobile', 'Branch', 'Year', 'Section', 'Registered On'];\n      const rows = allRegistrations.map((item, idx) => [\n        idx + 1,\n        `\"${item.id}\"`,\n        `\"${(item.name || '').replace(/\"/g, '\"\"')}\"`,\n        `\"${(item.email || '').replace(/\"/g, '\"\"')}\"`,\n        `\"${item.phone}\"`,\n        `\"${item.branch}\"`,\n        `\"${item.year} Year\"`,\n        `\"${item.section}\"`,\n        `\"${item.formattedDate || item.registeredAt || ''}\"`\n      ]);\n\n      const csvContent = 'data:text/csv;charset=utf-8,' + \n        [headers.join(','), ...rows.map(e => e.join(','))].join('\\n');\n      \n      const encodedUri = encodeURI(csvContent);\n      const link = document.createElement('a');\n      link.setAttribute('href', encodedUri);\n      link.setAttribute('download', `AWS_Community_Day_Registrations_${new Date().toISOString().slice(0, 10)}.csv`);\n      document.body.appendChild(link);\n      link.click();\n      link.remove();\n      showToast('CSV downloaded successfully! 📄');\n    });\n\n    // Filters event listeners\n    searchInput.addEventListener('input', renderTable);\n    branchFilter.addEventListener('change', renderTable);\n    yearFilter.addEventListener('change', renderTable);\n    document.getElementById('refreshBtn').addEventListener('click', () => {\n      loadData();\n      showToast('Data refreshed! 🔄');\n    });\n\n    // Settings Modal\n    const openSettingsBtn = document.getElementById('openSettingsBtn');\n    const closeSettingsModal = document.getElementById('closeSettingsModal');\n    const cancelSettingsBtn = document.getElementById('cancelSettingsBtn');\n\n    openSettingsBtn.addEventListener('click', () => {\n      adminWhatsAppInput.value = settings.adminWhatsApp || '';\n      settingsModal.classList.add('active');\n    });\n\n    function hideSettingsModal() {\n      settingsModal.classList.remove('active');\n    }\n\n    closeSettingsModal.addEventListener('click', hideSettingsModal);\n    cancelSettingsBtn.addEventListener('click', hideSettingsModal);\n\n    settingsForm.addEventListener('submit', async (e) => {\n      e.preventDefault();\n      const num = adminWhatsAppInput.value.replace(/[^0-9]/g, '');\n      settings.adminWhatsApp = num;\n\n      try {\n        await fetch('/api/settings', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ adminWhatsApp: num })\n        });\n      } catch (err) {\n        console.warn('Could not save to backend, stored locally:', err);\n      }\n\n      localStorage.setItem('aws_settings_cache', JSON.stringify(settings));\n      hideSettingsModal();\n      updateUI();\n      showToast('WhatsApp Settings Saved! 💬');\n    });\n\n    // Close on overlay click\n    window.addEventListener('click', (e) => {\n      if (e.target === settingsModal) hideSettingsModal();\n    });\n\n    // Check Authentication State\n    function checkAuth() {\n      const isAuth = sessionStorage.getItem('aws_admin_auth');\n      if (isAuth === 'true') {\n        loginView.style.display = 'none';\n        dashboardView.style.display = 'flex';\n        loadData();\n      } else {\n        loginView.style.display = 'flex';\n        dashboardView.style.display = 'none';\n      }\n    }\n\n    // Login Form Submit\n    adminLoginForm.addEventListener('submit', async function(e) {\n      e.preventDefault();\n      loginAlert.style.display = 'none';\n      loginSubmitBtn.disabled = true;\n      loginSubmitBtn.innerHTML = 'AUTHENTICATING... ⏳';\n\n      const u = loginUsername.value.trim();\n      const p = loginPassword.value.trim();\n\n      try {\n        const res = await fetch('/api/login', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ username: u, password: p })\n        });\n\n        if (res.ok) {\n          sessionStorage.setItem('aws_admin_auth', 'true');\n          loginUsername.value = '';\n          loginPassword.value = '';\n          checkAuth();\n          showToast('Welcome back, Admin! 🚀');\n          return;\n        } else {\n          throw new Error('Invalid credentials');\n        }\n      } catch (err) {\n        // Fallback local check\n        if (u === 'admin' && p === 'admin123') {\n          sessionStorage.setItem('aws_admin_auth', 'true');\n          loginUsername.value = '';\n          loginPassword.value = '';\n          checkAuth();\n          showToast('Welcome back, Admin! 🚀');\n          return;\n        }\n\n        loginAlert.style.display = 'block';\n        loginAlert.textContent = '⚠️ Invalid username or password. Please try again.';\n      } finally {\n        loginSubmitBtn.disabled = false;\n        loginSubmitBtn.innerHTML = '⚡ SIGN IN TO DASHBOARD &rarr;';\n      }\n    });\n\n    // Logout Action\n    logoutBtn.addEventListener('click', function() {\n      sessionStorage.removeItem('aws_admin_auth');\n      showToast('Logged out successfully. 🔒');\n      checkAuth();\n    });\n\n    // Initialize View with Auth Check\n    checkAuth();\n  </script>\n</body>\n</html>\n"};